238	static enum i2c_read_kind sensor_classify_read(ssize_t n, size_t expect)
239	{
240	  if (n == (ssize_t)expect)
241	    {
242	      return I2C_READ_DATA;
243	    }
244	
245	  if (n < 0 && (errno == EAGAIN || errno == EWOULDBLOCK || errno == EINTR))
246	    {
247	      return I2C_READ_EMPTY;
248	    }
249	
250	  return I2C_READ_ERR;
251	}
