316	/** @brief 调用方已持有 g_lock。 */
317	static void sensor_report_fault_locked(uint8_t id, uint32_t now_ms)
318	{
319	  struct board_fault_window *win;
320	
321	  if (id >= BOARD_LANE_COUNT)
322	    {
323	      return;
324	    }
325	
326	  win = &g_fault_win[id];
327	  if (win->count == 0 ||
328	      (uint32_t)(now_ms - win->first_ms) > I2C_SENSOR_FAULT_WINDOW_MS)
329	    {
330	      win->first_ms = now_ms;
331	      win->last_ms = 0;
332	      win->count = 0;
333	    }
334	
335	  if (win->last_ms != 0 &&
336	      (uint32_t)(now_ms - win->last_ms) < I2C_SENSOR_FAULT_SPACING_MS)
337	    {
338	      return;
339	    }
340	
341	  win->last_ms = now_ms;
342	  if (win->count < UINT8_MAX)
343	    {
344	      win->count++;
345	    }
346	
347	  if (g_fault_tot[id] < UINT16_MAX)
348	    {
349	      g_fault_tot[id]++;
350	    }
351	
352	  if (win->count >= I2C_SENSOR_FAULT_THRESHOLD &&
353	      sensor_lane_may_retry(id) &&
354	      !g_lane[id].busy && !g_lane[id].pending &&
355	      (g_lane[id].retry_at == 0 ||
356	       deadline_reached(now_ms, g_lane[id].retry_at)))
357	    {
358	      g_lane[id].pending = true;
359	      g_lane[id].retry_at = 0;
360	      LOGE("request reopen %s window=%u total=%u",
361	           lane_name(id), (unsigned)win->count,
362	           (unsigned)g_fault_tot[id]);
363	    }
364	}
