366	static void sensor_lane_finish_locked(uint8_t id, bool ok, uint32_t now_ms)
367	{
368	  g_lane[id].busy = false;
369	  g_lane[id].pending = false;
370	  if (ok)
371	    {
372	      g_lane[id].present = true;
373	    }
374	
375	  g_stall_ms[id] = 0;
376	  if (ok)
377	    {
378	      memset(&g_fault_win[id], 0, sizeof(g_fault_win[id]));
379	      g_lane[id].retry_at = 0;
380	      LOGI("reopen %s ok, cycles=%u",
381	           lane_name(id), (unsigned)g_reopen_cycles);
382	      return;
383	    }
384	
385	  g_lane[id].retry_at = now_ms + I2C_SENSOR_RETRY_MS;
386	  LOGE("reopen %s failed, retry in %u ms",
387	       lane_name(id), (unsigned)I2C_SENSOR_RETRY_MS);
388	}
