390	/** @brief 调用方已持有 g_lock。按时间戳判断停滞，保留旧样本不算故障。 */
391	static void sensor_watch_stale_locked(uint8_t id, bool want,
392	                                      uint32_t stamp_ms, uint32_t now_ms)
393	{
394	  uint32_t *stall;
395	
396	  if (!want || g_lane[id].busy)
397	    {
398	      g_stall_ms[id] = 0;
399	      return;
400	    }
401	
402	  if (stamp_ms != 0 &&
403	      myvendor_mono_elapsed_ms(now_ms, stamp_ms) < I2C_SENSOR_STALL_MS)
404	    {
405	      g_stall_ms[id] = 0;
406	      return;
407	    }
408	
409	  stall = &g_stall_ms[id];
410	  if (*stall == 0)
411	    {
412	      *stall = now_ms;
413	      return;
414	    }
415	
416	  if ((uint32_t)(now_ms - *stall) >= I2C_SENSOR_STALL_MS)
417	    {
418	      *stall = now_ms;
419	      sensor_report_fault_locked(id, now_ms);
420	    }
421	}
