446	/**
447	 * @brief 用滤波后的毫伏得到产品百分比（回差）。
448	 *
449	 * 不因充满 IO 钉 100%：该 IO 与空闲相同（STAT 高 + DISCHRG 高），钉死会
450	 * 让 3.98 V 仍显示满电。真满电由 OCV 曲线映射到 100%。
451	 */
452	static int bat_pct_ui(int filt_mv)
453	{
454	  int pct;
455	  int charging;
456	
457	  if (filt_mv < 0)
458	    {
459	      return g_bat_pct_ui;
460	    }
461	
462	  pct = bat_pct_from_mv(filt_mv);
463	  if (pct < 0)
464	    {
465	      return g_bat_pct_ui;
466	    }
467	
468	  charging = bat_charging();
469	  if (charging && g_bat_pct_ui >= 0 && pct < g_bat_pct_ui)
470	    {
471	      return g_bat_pct_ui;
472	    }
473	
474	  if (g_bat_pct_ui < 0)
475	    {
476	      g_bat_pct_ui = pct;
477	      return pct;
478	    }
479	
480	  if (pct >= g_bat_pct_ui + BOARD_SENSOR_BAT_HYST ||
481	      pct <= g_bat_pct_ui - BOARD_SENSOR_BAT_HYST)
482	    {
483	      g_bat_pct_ui = pct;
484	    }
485	
486	  return g_bat_pct_ui;
487	}
