489	/**
490	 * @brief 充电→充满、坐在充满 IO、或旧 4.10 V KV 已到 CV 时更新满电校准。
491	 *
492	 * 电压门槛在 ctl：低于约 4.05 V 的观测直接丢弃。
493	 * 已在充满 IO、或充电且 KV 仍是旧默认（约 4.10 V）而电压已到 CV。
494	 */
495	static void bat_maybe_cal(int mv)
496	{
497	  bool edge;
498	  bool full;
499	  int stored;
500	
501	  if (mv < 0)
502	    {
503	      return;
504	    }
505	
506	  edge = eta9184_take_full_edge();
507	  full = eta9184_charge_full();
508	  if (edge || full)
509	    {
510	      myvendor_devctl_bat_full_note(mv);
511	      return;
512	    }
513	
514	  if (!bat_charging() || !myvendor_devctl_bat_full_have())
515	    {
516	      return;
517	    }
518	
519	  stored = myvendor_devctl_bat_full_mv_get();
520	  if (stored < MYVENDOR_BAT_SOC_STALE_FULL_MAX &&
521	      mv >= MYVENDOR_BAT_SOC_STALE_OBS_MIN)
522	    {
523	      myvendor_devctl_bat_full_note(mv);
524	    }
525	}
