586	static void bat_fail_fd(int fd)
587	{
588	  pthread_mutex_lock(&g_lock);
589	  if (g_adc_fd == fd)
590	    {
591	      g_adc_fd = -1;
592	    }
593	
594	  pthread_mutex_unlock(&g_lock);
595	  if (fd >= 0)
596	    {
597	      close(fd);
598	    }
599	
600	  g_adc_conv = false;
601	}
602	
603	/**
604	 * @brief 第一次只 TRIGGER；之后先 read 上次转换，再 TRIGGER 下一次。
605	 *
606	 * 不要在 TRIGGER 后立刻 read：FIFO 空时会 SemWait。转换结果在 FIFO 里
607	 * 等到下一拍再取，本拍只启动下一次转换。
608	 */
609	static void bat_poll(uint32_t now_ms)
610	{
611	  int fd;
612	  int ret;
613	  ssize_t n;
614	  struct adc_msg_s msg;
615	  int mv;
616	
617	  pthread_mutex_lock(&g_lock);
618	  fd = g_adc_fd;
619	  pthread_mutex_unlock(&g_lock);
620	  if (fd < 0)
621	    {
622	      return;
623	    }
624	
625	  if (g_adc_conv)
626	    {
627	      n = read(fd, &msg, sizeof(msg));
628	      if (n != (ssize_t)sizeof(msg))
629	        {
630	          bat_fail_fd(fd);
631	          return;
632	        }
633	
634	      mv = (int)msg.am_data;
635	      if (g_bat_ema < 0)
636	        {
637	          g_bat_ema = mv;
638	        }
639	      else
640	        {
641	          g_bat_ema += (mv - g_bat_ema) / BOARD_SENSOR_BAT_EMA;
642	        }
643	
644	      bat_maybe_cal(g_bat_ema);
645	      (void)bat_pct_ui(g_bat_ema);
646	      bat_publish(mv, g_bat_pct_ui, now_ms);
647	    }
648	  else
649	    {
