726	static void sensor_accel_lp_locked(float x, float y, float z)
727	{
728	  float n = sqrtf(x * x + y * y + z * z);
729	
730	  if (n < I2C_SENSOR_G_MIN || n > I2C_SENSOR_G_MAX)
731	    {
732	      return;
733	    }
734	
735	  if (!g_accel_f_have)
736	    {
737	      g_accel_f.x = x;
738	      g_accel_f.y = y;
739	      g_accel_f.z = z;
740	      g_accel_f.valid = true;
741	      g_accel_f_have = true;
742	      return;
743	    }
744	
745	  g_accel_f.x += I2C_SENSOR_ACCEL_LP_A * (x - g_accel_f.x);
746	  g_accel_f.y += I2C_SENSOR_ACCEL_LP_A * (y - g_accel_f.y);
747	  g_accel_f.z += I2C_SENSOR_ACCEL_LP_A * (z - g_accel_f.z);
748	}
