750	static void imu_poll(uint32_t now_ms)
751	{
752	  int accel_fd;
753	  int gyro_fd;
754	  struct sensor_accel accel;
755	  struct sensor_gyro gyro;
756	  enum i2c_read_kind accel_kind = I2C_READ_EMPTY;
757	  enum i2c_read_kind gyro_kind = I2C_READ_EMPTY;
758	  ssize_t n;
759	
760	  pthread_mutex_lock(&g_lock);
761	  accel_fd = g_accel_fd;
762	  gyro_fd  = g_gyro_fd;
763	  pthread_mutex_unlock(&g_lock);
764	  if (accel_fd < 0 || gyro_fd < 0)
765	    {
766	      return;
767	    }
768	
769	  n = read(accel_fd, &accel, sizeof(accel));
770	  accel_kind = sensor_classify_read(n, sizeof(accel));
771	  n = read(gyro_fd, &gyro, sizeof(gyro));
772	  gyro_kind = sensor_classify_read(n, sizeof(gyro));
773	
774	  pthread_mutex_lock(&g_lock);
775	  if (accel_kind == I2C_READ_DATA)
776	    {
777	      g_accel.valid = true;
778	      g_accel.x = accel.x;
779	      g_accel.y = accel.y;
780	      g_accel.z = accel.z;
781	      g_accel_ms = now_ms;
782	      sensor_accel_lp_locked(accel.x, accel.y, accel.z);
783	    }
784	  else if (accel_kind == I2C_READ_ERR)
785	    {
786	      sensor_report_fault_locked(BOARD_LANE_IMU, now_ms);
787	    }
788	
789	  if (gyro_kind == I2C_READ_DATA)
790	    {
791	      g_gyro.valid = true;
792	      g_gyro.x = gyro.x;
793	      g_gyro.y = gyro.y;
794	      g_gyro.z = gyro.z;
795	      g_gyro_ms = now_ms;
796	    }
797	  else if (gyro_kind == I2C_READ_ERR)
798	    {
799	      sensor_report_fault_locked(BOARD_LANE_IMU, now_ms);
800	    }
801	
802	  pthread_mutex_unlock(&g_lock);
803	}
