1058	static void sensor_supervisor_tick_locked(uint32_t now_ms)
1059	{
1060	  uint8_t i;
1061	
1062	  for (i = 0; i < BOARD_LANE_COUNT; i++)
1063	    {
1064	      if (!sensor_lane_may_retry(i) ||
1065	          g_lane[i].busy || g_lane[i].pending ||
1066	          g_lane[i].retry_at == 0 ||
1067	          !deadline_reached(now_ms, g_lane[i].retry_at))
1068	        {
1069	          continue;
1070	        }
1071	
1072	      g_lane[i].pending = true;
1073	      g_lane[i].retry_at = 0;
1074	      LOGI("retry %s", lane_name(i));
1075	    }
1076	
1077	  for (i = 0; i < BOARD_LANE_COUNT; i++)
1078	    {
1079	      if (g_ops[i].watch_locked != NULL)
1080	        {
1081	          g_ops[i].watch_locked(now_ms);
1082	        }
1083	    }
1084	}
