1086	/** @brief close/open 走 I2C activate，必须在 g_lock 外执行。只动这一路。 */
1087	static void sensor_reopen_lane(uint8_t id, uint32_t now_ms)
1088	{
1089	  const struct board_lane_ops *ops;
1090	  bool ok = false;
1091	
1092	  if (id >= BOARD_LANE_COUNT)
1093	    {
1094	      return;
1095	    }
1096	
1097	  ops = &g_ops[id];
1098	  if (ops->open == NULL || ops->take_locked == NULL ||
1099	      ops->close == NULL || ops->install_locked == NULL)
1100	    {
1101	      return;
1102	    }
1103	
1104	  pthread_mutex_lock(&g_lock);
1105	  if (g_lane[id].busy)
1106	    {
1107	      pthread_mutex_unlock(&g_lock);
1108	      return;
1109	    }
1110	
1111	  g_lane[id].busy = true;
1112	  g_lane[id].pending = false;
1113	  if (g_reopen_cycles < UINT16_MAX)
1114	    {
1115	      g_reopen_cycles++;
1116	    }
1117	
1118	  if (ops->reopen_begin_locked != NULL)
1119	    {
1120	      ops->reopen_begin_locked();
1121	    }
1122	
1123	  ops->take_locked();
1124	  pthread_mutex_unlock(&g_lock);
1125	
1126	  LOGI("reopen %s begin cycles=%u",
1127	       lane_name(id), (unsigned)g_reopen_cycles);
1128	
1129	  ops->close();
1130	  usleep(I2C_SENSOR_REOPEN_GAP_US);
1131	  if (ops->recover_hw != NULL)
1132	    {
1133	      ops->recover_hw();
1134	    }
1135	
1136	  ok = (ops->open() == 0);
1137	  pthread_mutex_lock(&g_lock);
1138	  ops->install_locked(ok);
1139	  if (!ok)
1140	    {
1141	      pthread_mutex_unlock(&g_lock);
1142	      ops->close();
1143	      pthread_mutex_lock(&g_lock);
1144	    }
1145	
1146	  sensor_lane_finish_locked(id, ok, now_ms);
1147	  pthread_mutex_unlock(&g_lock);
1148	}
