1150	static void sensor_open_all(void)
1151	{
1152	  uint8_t i;
1153	  uint32_t now = sensor_now_ms();
1154	
1155	  for (i = 0; i < BOARD_LANE_COUNT; i++)
1156	    {
1157	      bool ok;
1158	
1159	      if (g_ops[i].open == NULL || g_ops[i].install_locked == NULL)
1160	        {
1161	          continue;
1162	        }
1163	
1164	      ok = (g_ops[i].open() == 0);
1165	      pthread_mutex_lock(&g_lock);
1166	      g_ops[i].install_locked(ok);
1167	      g_lane[i].present = ok;
1168	      if (!ok && g_ops[i].always_retry)
1169	        {
1170	          g_lane[i].retry_at = now + I2C_SENSOR_RETRY_MS;
1171	          LOGE("initial open %s failed", lane_name(i));
1172	        }
1173	
1174	      pthread_mutex_unlock(&g_lock);
1175	      if (!ok && g_ops[i].close != NULL)
1176	        {
1177	          g_ops[i].close();
1178	        }
1179	    }
1180	}
1181	
1182	static void sensor_close_all(void)
1183	{
1184	  uint8_t i;
1185	
1186	  pthread_mutex_lock(&g_lock);
1187	  for (i = 0; i < BOARD_LANE_COUNT; i++)
1188	    {
1189	      if (g_ops[i].take_locked != NULL)
1190	        {
1191	          g_ops[i].take_locked();
1192	        }
1193	    }
1194	
1195	  pthread_mutex_unlock(&g_lock);
1196	
1197	  for (i = 0; i < BOARD_LANE_COUNT; i++)
1198	    {
1199	      if (g_ops[i].close != NULL)
1200	        {
1201	          g_ops[i].close();
1202	        }
1203	    }
1204	}
