1206	static void *sensor_thread(void *arg)
1207	{
1208	  (void)arg;
1209	
1210	  sensor_open_all();
1211	  pthread_mutex_lock(&g_lock);
1212	  g_running = true;
1213	  pthread_mutex_unlock(&g_lock);
1214	
1215	  while (g_running)
1216	    {
1217	      uint32_t now = sensor_now_ms();
1218	      int reopen_id = -1;
1219	      uint8_t i;
1220	
1221	      for (i = 0; i < BOARD_LANE_COUNT; i++)
1222	        {
1223	          if (g_ops[i].poll == NULL || g_ops[i].period_ms == 0 ||
1224	              g_lane[i].busy)
1225	            {
1226	              continue;
1227	            }
1228	
1229	          if (g_lane[i].last_ms != 0 &&
1230	              (uint32_t)(now - g_lane[i].last_ms) < g_ops[i].period_ms)
1231	            {
1232	              continue;
1233	            }
1234	
1235	          g_ops[i].poll(now);
1236	          g_lane[i].last_ms = now;
1237	        }
1238	
1239	      pthread_mutex_lock(&g_lock);
1240	      sensor_supervisor_tick_locked(now);
1241	      for (i = 0; i < BOARD_LANE_COUNT; i++)
1242	        {
1243	          if (g_lane[i].pending && !g_lane[i].busy)
1244	            {
1245	              reopen_id = (int)i;
1246	              break;
1247	            }
1248	        }
1249	
1250	      pthread_mutex_unlock(&g_lock);
1251	
1252	      if (reopen_id >= 0)
1253	        {
1254	          sensor_reopen_lane((uint8_t)reopen_id, now);
1255	        }
1256	
1257	      usleep(I2C_SENSOR_LOOP_MS * 1000);
1258	    }
1259	
1260	  sensor_close_all();
1261	  return NULL;
1262	}
