1264	int myvendor_board_sensor_start(void)
1265	{
1266	  pthread_attr_t attr;
1267	  pthread_t th;
1268	  struct sched_param sp;
1269	  int ret;
1270	
1271	  if (g_started)
1272	    {
1273	      return 0;
1274	    }
1275	
1276	  pthread_attr_init(&attr);
1277	  ret = pthread_attr_setstack(&attr, g_stack, sizeof(g_stack));
1278	  sp.sched_priority = I2C_SENSOR_PRIO;
1279	#ifdef PTHREAD_EXPLICIT_SCHED
1280	  (void)pthread_attr_setinheritsched(&attr, PTHREAD_EXPLICIT_SCHED);
1281	#endif
1282	  (void)pthread_attr_setschedparam(&attr, &sp);
1283	  if (ret == 0)
1284	    {
1285	      ret = pthread_create(&th, &attr, sensor_thread, NULL);
1286	    }
1287	
1288	  pthread_attr_destroy(&attr);
1289	  if (ret != 0)
1290	    {
1291	      LOGE("thread create failed %d", ret);
1292	      return -ret;
1293	    }
1294	
1295	#ifndef CONFIG_DISABLE_PTHREAD
1296	  pthread_setname_np(th, "board_sensor");
1297	#endif
1298	  pthread_detach(th);
1299	  g_started = true;
1300	  LOGI("board sensor thread started prio=%d", I2C_SENSOR_PRIO);
1301	  return 0;
1302	}
1303	
1304	bool myvendor_board_sensor_alive(void)
1305	{
