1310	{
1311	  uint8_t i;
1312	
1313	  pthread_mutex_lock(&g_lock);
1314	  if (!g_started)
1315	    {
1316	      pthread_mutex_unlock(&g_lock);
1317	      return;
1318	    }
1319	
1320	  for (i = 0; i < BOARD_LANE_COUNT; i++)
1321	    {
1322	      if (g_lane[i].busy || !sensor_lane_may_retry(i))
1323	        {
1324	          continue;
1325	        }
1326	
1327	      g_lane[i].pending = true;
1328	      g_lane[i].retry_at = 0;
1329	    }
1330	
1331	  LOGI("reopen requested");
1332	  pthread_mutex_unlock(&g_lock);
1333	}
