252	static int bmp388_reg_update(FAR struct bmp388_dev_s *priv, uint8_t reg,
253	                             uint8_t mask, uint8_t val)
254	{
255	  uint8_t oldv;
256	  uint8_t newv;
257	  int ret;
258	
259	  ret = bmp388_getreg8(priv, reg, &oldv);
260	  if (ret < 0)
261	    {
262	      return ret;
263	    }
264	
265	  newv = (oldv & ~mask) | (val & mask);
266	  if (newv == oldv)
267	    {
268	      return OK;
269	    }
270	
271	  return bmp388_putreg8(priv, reg, newv);
272	}
