296	static int bmp388_load_calib(FAR struct bmp388_dev_s *priv)
297	{
298	  uint8_t buf[sizeof(struct bmp388_calib_s)];
299	  int ret;
300	
301	  ret = bmp388_getregs(priv, BMP388_REG_CALIB0, buf, sizeof(buf));
302	  if (ret < 0)
303	    {
304	      return ret;
305	    }
306	
307	  priv->calib.t1  = bmp388_le16(&buf[0]);
308	  priv->calib.t2  = bmp388_le16(&buf[2]);
309	  priv->calib.t3  = (int8_t)buf[4];
310	  priv->calib.p1  = bmp388_le16s(&buf[5]);
311	  priv->calib.p2  = bmp388_le16s(&buf[7]);
312	  priv->calib.p3  = (int8_t)buf[9];
313	  priv->calib.p4  = (int8_t)buf[10];
314	  priv->calib.p5  = bmp388_le16(&buf[11]);
315	  priv->calib.p6  = bmp388_le16(&buf[13]);
316	  priv->calib.p7  = (int8_t)buf[15];
317	  priv->calib.p8  = (int8_t)buf[16];
318	  priv->calib.p9  = bmp388_le16s(&buf[17]);
319	  priv->calib.p10 = (int8_t)buf[19];
320	  priv->calib.p11 = (int8_t)buf[20];
321	
322	  return OK;
323	}
