325	static int bmp388_hw_init(FAR struct bmp388_dev_s *priv)
326	{
327	  uint8_t err;
328	  int ret;
329	
330	  syslog(LOG_INFO, "BRINGUP: BMP388 hw_init enter\n");
331	
332	  ret = bmp388_putreg8(priv, BMP388_REG_CMD, BMP388_CMD_SOFT_RESET);
333	  if (ret < 0)
334	    {
335	      return ret;
336	    }
337	
338	  up_mdelay(10);
339	
340	  ret = bmp388_checkid(priv);
341	  if (ret < 0)
342	    {
343	      return ret;
344	    }
345	
346	  ret = bmp388_load_calib(priv);
347	  if (ret < 0)
348	    {
349	      return ret;
350	    }
351	
352	  ret = bmp388_putreg8(priv, BMP388_REG_ODR, BMP388_DEFAULT_ODR);
353	  if (ret < 0)
354	    {
355	      return ret;
356	    }
357	
358	  ret = bmp388_putreg8(priv, BMP388_REG_OSR, BMP388_DEFAULT_OSR);
359	  if (ret < 0)
360	    {
361	      return ret;
362	    }
363	
364	  ret = bmp388_putreg8(priv, BMP388_REG_CONFIG, 0);
365	  if (ret < 0)
366	    {
367	      return ret;
368	    }
369	
370	  ret = bmp388_putreg8(priv, BMP388_REG_PWR_CTRL, BMP388_PWR_CTRL_MODE_SLEEP);
371	  if (ret < 0)
372	    {
373	      return ret;
374	    }
375	
376	  ret = bmp388_getreg8(priv, BMP388_REG_ERR_REG, &err);
377	  if (ret < 0)
378	    {
379	      return ret;
380	    }
381	
382	  if (err & BMP388_STATUS_CONF_ERR)
383	    {
384	      snerr("BMP388 OSR/ODR configuration error\n");
385	      return -EINVAL;
386	    }
387	
388	  syslog(LOG_INFO, "BRINGUP: BMP388 hw_init ok\n");
389	  return OK;
390	}
