392	static void bmp388_compensate_temp(FAR struct bmp388_dev_s *priv)
393	{
394	  int64_t partial_data1;
395	  int64_t partial_data2;
396	  int64_t partial_data3;
397	  int64_t partial_data4;
398	  int64_t partial_data5;
399	  FAR struct bmp388_calib_s *cal = &priv->calib;
400	  FAR struct bmp388_sample_s *sample = &priv->sample;
401	
402	  partial_data1 = ((int64_t)sample->raw_temp - ((int64_t)256 * cal->t1));
403	  partial_data2 = (int64_t)cal->t2 * partial_data1;
404	  partial_data3 = partial_data1 * partial_data1;
405	  partial_data4 = partial_data3 * (int64_t)cal->t3;
406	  partial_data5 = ((partial_data2 * 262144) + partial_data4);
407	
408	  sample->comp_temp = partial_data5 / 4294967296;
409	}
410	
411	static uint64_t bmp388_compensate_press(FAR struct bmp388_dev_s *priv)
412	{
413	  int64_t partial_data1;
414	  int64_t partial_data2;
415	  int64_t partial_data3;
416	  int64_t partial_data4;
417	  int64_t partial_data5;
418	  int64_t partial_data6;
419	  int64_t offset;
420	  int64_t sensitivity;
421	  uint64_t comp_press;
422	  FAR struct bmp388_calib_s *cal = &priv->calib;
423	  FAR struct bmp388_sample_s *sample = &priv->sample;
424	  int64_t t_lin = sample->comp_temp;
425	  uint32_t raw_pressure = sample->press;
426	
427	  if (sample->comp_temp == 0)
428	    {
429	      bmp388_compensate_temp(priv);
430	      t_lin = sample->comp_temp;
431	    }
432	
433	  partial_data1 = t_lin * t_lin;
434	  partial_data2 = partial_data1 / 64;
435	  partial_data3 = (partial_data2 * t_lin) / 256;
436	  partial_data4 = ((int64_t)cal->p8 * partial_data3) / 32;
437	  partial_data5 = ((int64_t)cal->p7 * partial_data1) * 16;
438	  partial_data6 = ((int64_t)cal->p6 * t_lin) * 4194304;
439	  offset = ((int64_t)cal->p5 * 140737488355328LL) + partial_data4 +
440	           partial_data5 + partial_data6;
441	
442	  partial_data2 = ((int64_t)cal->p4 * partial_data3) / 32;
443	  partial_data4 = ((int64_t)cal->p3 * partial_data1) * 4;
444	  partial_data5 = ((int64_t)cal->p2 - 16384) * t_lin * 2097152;
445	  sensitivity = ((int64_t)cal->p1 - 16384) * 70368744177664LL +
446	                partial_data2 + partial_data4 + partial_data5;
447	
448	  partial_data1 = (sensitivity / 16777216) * raw_pressure;
449	  partial_data2 = (int64_t)cal->p10 * t_lin;
450	  partial_data3 = partial_data2 + ((int64_t)65536 * cal->p9);
451	  partial_data4 = (partial_data3 * raw_pressure) / 8192;
452	  partial_data5 = (raw_pressure * (partial_data4 / 10)) / 512;
453	  partial_data5 = partial_data5 * 10;
454	  partial_data6 = ((int64_t)raw_pressure * (int64_t)raw_pressure);
455	  partial_data2 = ((int64_t)cal->p11 * partial_data6) / 65536;
456	  partial_data3 = (partial_data2 * raw_pressure) / 128;
457	  partial_data4 = (offset / 4) + partial_data1 + partial_data5 +
458	                  partial_data3;
459	
460	  comp_press = (((uint64_t)partial_data4 * 25) / (uint64_t)1099511627776ULL);
461	
462	  return comp_press;
463	}
464	
465	static int bmp388_wait_drdy(FAR struct bmp388_dev_s *priv)
466	{
467	  uint8_t status = 0;
468	  int elapsed = 0;
469	
470	  while (elapsed < BMP388_FETCH_TIMEOUT_MS)
471	    {
472	      int ret = bmp388_getreg8(priv, BMP388_REG_STATUS, &status);
473	
474	      if (ret < 0)
475	        {
476	          return ret;
477	        }
478	
479	      if ((status & BMP388_STATUS_DRDY) == BMP388_STATUS_DRDY)
480	        {
481	          return OK;
482	        }
483	
484	      nxsig_usleep(5000);
485	      elapsed += 5;
486	    }
487	
488	  return -ETIMEDOUT;
489	}
490	
491	static int bmp388_read_sample(FAR struct bmp388_dev_s *priv)
492	{
493	  uint8_t raw[BMP388_SAMPLE_SIZE];
494	  int ret;
495	
496	  /* Forced mode: one shot, then chip returns to sleep (BMP388 datasheet 3.3.2). */
497	
498	  ret = bmp388_putreg8(priv, BMP388_REG_PWR_CTRL, BMP388_PWR_CTRL_FORCED);
499	  if (ret < 0)
500	    {
501	      return ret;
502	    }
503	
504	  ret = bmp388_wait_drdy(priv);
505	  if (ret < 0)
506	    {
507	      /* Fall back to typical conversion time if status bits stay cleared. */
508	
509	      nxsig_usleep(BMP388_FORCED_DELAY_MS * 1000);
510	    }
511	
512	  ret = bmp388_getregs(priv, BMP388_REG_DATA0, raw, sizeof(raw));
513	  if (ret < 0)
514	    {
515	      return ret;
516	    }
517	
518	  priv->sample.press = bmp388_le24(&raw[0]);
519	  priv->sample.raw_temp = bmp388_le24(&raw[3]);
520	  priv->sample.comp_temp = 0;
521	
522	  return OK;
523	}
