525	static int bmp388_set_interval(FAR struct sensor_lowerhalf_s *lower,
526	                               FAR struct file *filep,
527	                               FAR uint32_t *period_us)
528	{
529	  UNUSED(lower);
530	  UNUSED(filep);
531	  UNUSED(period_us);
532	  return OK;
533	}
534	
535	static int bmp388_activate(FAR struct sensor_lowerhalf_s *lower,
536	                           FAR struct file *filep, bool enable)
537	{
538	  FAR struct bmp388_dev_s *priv = container_of(lower,
539	                                               struct bmp388_dev_s,
540	                                               sensor_lower);
541	  int ret;
542	
543	  if (enable)
544	    {
545	      /* Subscriber open: keep chip in sleep; fetch triggers forced mode. */
546	
547	      priv->activated = true;
548	      return OK;
549	    }
550	
551	  ret = bmp388_reg_update(priv, BMP388_REG_PWR_CTRL,
552	                          BMP388_PWR_CTRL_MODE_MASK,
553	                          BMP388_PWR_CTRL_MODE_SLEEP);
554	  if (ret >= 0)
555	    {
556	      priv->activated = false;
557	    }
558	
559	  return ret;
560	}
561	
562	static int bmp388_fetch(FAR struct sensor_lowerhalf_s *lower,
563	                        FAR struct file *filep,
564	                        FAR char *buffer, size_t buflen)
565	{
566	  FAR struct bmp388_dev_s *priv = container_of(lower,
567	                                               struct bmp388_dev_s,
568	                                               sensor_lower);
569	  struct sensor_baro baro;
570	  struct timespec ts;
571	  uint64_t comp_press;
572	  int64_t temp_q;
573	  int ret;
574	
575	  UNUSED(filep);
576	
577	  if (buflen != sizeof(baro))
578	    {
579	      return -EINVAL;
580	    }
581	
582	  ret = bmp388_read_sample(priv);
583	  if (ret < 0)
584	    {
585	      return ret;
586	    }
587	
588	  bmp388_compensate_temp(priv);
589	  comp_press = bmp388_compensate_press(priv);
590	
591	  temp_q = (priv->sample.comp_temp * 250000) / 16384;
592	
593	  clock_systime_timespec(&ts);
594	  baro.timestamp = 1000000ull * ts.tv_sec + ts.tv_nsec / 1000;
595	  baro.pressure = (float)comp_press / 10000.0f;
596	  baro.temperature = (float)temp_q / 1000000.0f;
597	
598	  memcpy(buffer, &baro, sizeof(baro));
599	  return (int)sizeof(baro);
600	}
