606	int bmp388_register(int devno, FAR struct i2c_master_s *i2c)
607	{
608	  FAR struct bmp388_dev_s *priv;
609	  int ret;
610	
611	  if (i2c == NULL)
612	    {
613	      return -EINVAL;
614	    }
615	
616	  priv = kmm_zalloc(sizeof(*priv));
617	  if (priv == NULL)
618	    {
619	      return -ENOMEM;
620	    }
621	
622	  priv->i2c = i2c;
623	  priv->addr = CONFIG_BOARD_BMP388_I2C_ADDR;
624	  priv->freq = CONFIG_BOARD_BMP388_I2C_FREQUENCY;
625	  priv->sensor_lower.ops = &g_bmp388_sensor_ops;
626	  priv->sensor_lower.type = SENSOR_TYPE_BAROMETER;
627	
628	  ret = bmp388_hw_init(priv);
629	  if (ret < 0)
630	    {
631	      kmm_free(priv);
632	      return ret;
633	    }
634	
635	  ret = sensor_register(&priv->sensor_lower, devno);
636	  if (ret < 0)
637	    {
638	      snerr("sensor_register failed: %d\n", ret);
639	      kmm_free(priv);
640	      return ret;
641	    }
642	
643	  sninfo("BMP388 registered as /dev/uorb/sensor_baro%d\n", devno);
644	  return OK;
645	}
