129	/* Board mount: MMC5983MA on PCB rear. Displayed heading needed 270°
130	 * clockwise from the previous 180° map: (x, y) -> (-y, x). Z inverted
131	 * because the package faces away from the screen.
132	 */
133	
134	static void mmc5983ma_board_axes(FAR float *x, FAR float *y, FAR float *z)
135	{
136	  float cx = *x;
137	  float cy = *y;
138	
139	  *x = -cy;
140	  *y = cx;
141	  *z = -(*z);
142	}
