150	static int mmc5983ma_getreg8(FAR struct mmc5983ma_dev_s *priv, uint8_t regaddr,
151	                             FAR uint8_t *regval)
152	{
153	  struct i2c_msg_s msgs[2];
154	  int ret;
155	
156	  msgs[0].frequency = priv->freq;
157	  msgs[0].addr      = priv->addr;
158	  msgs[0].flags     = 0;
159	  msgs[0].buffer    = &regaddr;
160	  msgs[0].length    = 1;
161	
162	  msgs[1].frequency = priv->freq;
163	  msgs[1].addr      = priv->addr;
164	  msgs[1].flags     = I2C_M_READ;
165	  msgs[1].buffer    = regval;
166	  msgs[1].length    = 1;
167	
168	  ret = mmc5983ma_transfer(priv, msgs, 2);
169	  return ret < 0 ? ret : OK;
170	}
171	
172	static int mmc5983ma_putreg8(FAR struct mmc5983ma_dev_s *priv, uint8_t regaddr,
173	                             uint8_t regval)
174	{
175	  struct i2c_msg_s msg;
176	  uint8_t buf[2];
177	  int ret;
178	
179	  buf[0] = regaddr;
180	  buf[1] = regval;
181	
182	  msg.frequency = priv->freq;
183	  msg.addr      = priv->addr;
184	  msg.flags     = 0;
185	  msg.buffer    = buf;
186	  msg.length    = 2;
187	
188	  ret = mmc5983ma_transfer(priv, &msg, 1);
189	  return ret < 0 ? ret : OK;
190	}
