196	  int ret;
197	
198	  msgs[0].frequency = priv->freq;
199	  msgs[0].addr      = priv->addr;
200	  msgs[0].flags     = 0;
201	  msgs[0].buffer    = &regaddr;
202	  msgs[0].length    = 1;
203	
204	  msgs[1].frequency = priv->freq;
205	  msgs[1].addr      = priv->addr;
206	  msgs[1].flags     = I2C_M_READ;
207	  msgs[1].buffer    = buffer;
