214	static int mmc5983ma_checkid(FAR struct mmc5983ma_dev_s *priv)
215	{
216	  uint8_t prodid;
217	  int ret;
218	
219	  ret = mmc5983ma_getreg8(priv, MMC5983MA_REG_PROD_ID, &prodid);
220	  if (ret < 0)
221	    {
222	      return ret;
223	    }
224	
225	  syslog(LOG_INFO, "BRINGUP: MMC5983MA product id: 0x%02x\n", prodid);
226	
227	  if (prodid != MMC5983MA_PROD_ID_VAL)
228	    {
229	      syslog(LOG_ERR,
230	             "BRINGUP: MMC5983MA unexpected product id 0x%02x\n", prodid);
231	      return -ENODEV;
232	    }
233	
234	  return OK;
235	}
236	
237	static void mmc5983ma_ctrl1_bandwidth(FAR struct mmc5983ma_dev_s *priv,
238	                                      int bandwidth_hz)
239	{
240	  priv->ctrl1_shadow &= ~(MMC5983MA_CTRL1_BW0 | MMC5983MA_CTRL1_BW1);
241	
242	  switch (bandwidth_hz)
243	    {
244	      case 800:
245	        priv->ctrl1_shadow |= MMC5983MA_CTRL1_BW1;
246	        break;
247	
248	      case 400:
249	        priv->ctrl1_shadow |= MMC5983MA_CTRL1_BW0 | MMC5983MA_CTRL1_BW1;
250	        break;
251	
252	      case 200:
253	        priv->ctrl1_shadow |= MMC5983MA_CTRL1_BW0;
254	        break;
255	
256	      default:
257	        /* 100 Hz */
258	        break;
259	    }
260	}
261	
262	static int mmc5983ma_hw_init(FAR struct mmc5983ma_dev_s *priv)
263	{
264	  int ret;
265	
266	  syslog(LOG_INFO, "BRINGUP: MMC5983MA hw_init enter\n");
267	
268	  ret = mmc5983ma_checkid(priv);
269	  if (ret < 0)
270	    {
271	      return ret;
272	    }
273	
274	  priv->ctrl0_shadow = MMC5983MA_CTRL0_AUTO_SR_EN;
275	  priv->ctrl1_shadow = 0;
276	
277	  mmc5983ma_ctrl1_bandwidth(priv, MMC5983MA_DEFAULT_BW_HZ);
278	
279	  /* Software reset via shadow register (avoid read-modify-write quirks). */
280	
281	  ret = mmc5983ma_putreg8(priv, MMC5983MA_REG_CTRL1,
282	                          priv->ctrl1_shadow | MMC5983MA_CTRL1_SW_RST);
283	  if (ret < 0)
284	    {
285	      return ret;
286	    }
287	
288	  up_mdelay(MMC5983MA_RESET_DELAY_MS);
289	
290	  ret = mmc5983ma_putreg8(priv, MMC5983MA_REG_CTRL1, priv->ctrl1_shadow);
291	  if (ret < 0)
292	    {
293	      return ret;
294	    }
295	
296	  ret = mmc5983ma_putreg8(priv, MMC5983MA_REG_CTRL0, priv->ctrl0_shadow);
297	  if (ret >= 0)
298	    {
299	      syslog(LOG_INFO, "BRINGUP: MMC5983MA hw_init ok\n");
300	    }
301	
302	  return ret;
303	}
304	
305	static uint32_t mmc5983ma_parse_axis(FAR const uint8_t *raw, int shift)
306	{
307	  uint32_t value;
308	
309	  value  = ((uint32_t)raw[0] << 10);
310	  value |= ((uint32_t)raw[1] << 2);
311	  value |= ((uint32_t)raw[2] >> shift) & 0x03;
312	
313	  return value;
314	}
315	
316	static float mmc5983ma_raw_to_ut(int32_t raw)
317	{
318	  float centered;
319	
320	  centered = (float)(raw - MMC5983MA_OFFSET_CENTER);
321	  return centered * MMC5983MA_FULLSCALE_GAUSS * MMC5983MA_GAUSS_TO_UT /
322	         MMC5983MA_SCALE_DIVISOR;
323	}
324	
325	static int mmc5983ma_wait_meas_done(FAR struct mmc5983ma_dev_s *priv)
326	{
327	  int elapsed = 0;
328	  uint8_t status;
329	  int ret;
330	
331	  while (elapsed < MMC5983MA_FETCH_TIMEOUT_MS)
332	    {
333	      ret = mmc5983ma_getreg8(priv, MMC5983MA_REG_STATUS, &status);
334	      if (ret < 0)
335	        {
336	          return ret;
337	        }
338	
339	      if ((status & MMC5983MA_STATUS_MEAS_M_DONE) != 0)
340	        {
341	          return OK;
342	        }
343	
344	      nxsig_usleep(1000);
345	      elapsed++;
346	    }
347	
348	  return -ETIMEDOUT;
349	}
350	
351	static int mmc5983ma_read_temp(FAR struct mmc5983ma_dev_s *priv,
352	                               FAR float *temp_c)
353	{
354	  uint8_t status;
355	  uint8_t tout;
356	  int elapsed = 0;
357	  int ret;
358	
359	  if (temp_c == NULL)
360	    {
361	      return OK;
362	    }
363	
364	  priv->ctrl0_shadow |= MMC5983MA_CTRL0_TM_T;
365	
366	  ret = mmc5983ma_putreg8(priv, MMC5983MA_REG_CTRL0, priv->ctrl0_shadow);
367	  if (ret < 0)
368	    {
369	      priv->ctrl0_shadow &= ~MMC5983MA_CTRL0_TM_T;
370	      *temp_c = 0.0f;
371	      return ret;
372	    }
373	
374	  while (elapsed < MMC5983MA_FETCH_TIMEOUT_MS)
375	    {
376	      ret = mmc5983ma_getreg8(priv, MMC5983MA_REG_STATUS, &status);
377	      if (ret < 0)
378	        {
379	          break;
380	        }
381	
382	      if ((status & MMC5983MA_STATUS_MEAS_T_DONE) != 0)
383	        {
384	          break;
385	        }
386	
387	      nxsig_usleep(1000);
388	      elapsed++;
389	    }
390	
391	  priv->ctrl0_shadow &= ~MMC5983MA_CTRL0_TM_T;
392	
393	  ret = mmc5983ma_getreg8(priv, MMC5983MA_REG_TOUT, &tout);
394	  if (ret < 0)
395	    {
396	      *temp_c = 0.0f;
397	      return ret;
398	    }
399	
400	  *temp_c = -75.0f + ((float)tout * 200.0f / 255.0f);
401	  return OK;
402	}
403	
404	static int mmc5983ma_read_sample(FAR struct mmc5983ma_dev_s *priv,
405	                                 FAR int32_t *x, FAR int32_t *y,
406	                                 FAR int32_t *z, FAR float *temp_c)
407	{
408	  uint8_t raw[7];
409	  int ret;
410	
411	  priv->ctrl0_shadow |= MMC5983MA_CTRL0_TM_M;
412	
413	  ret = mmc5983ma_putreg8(priv, MMC5983MA_REG_CTRL0, priv->ctrl0_shadow);
414	  if (ret < 0)
415	    {
416	      priv->ctrl0_shadow &= ~MMC5983MA_CTRL0_TM_M;
417	      return ret;
418	    }
419	
420	  ret = mmc5983ma_wait_meas_done(priv);
421	  priv->ctrl0_shadow &= ~MMC5983MA_CTRL0_TM_M;
422	
423	  if (ret < 0)
424	    {
425	      /* Fall through and return the last latched field values. */
426	    }
427	
428	  ret = mmc5983ma_getregs(priv, MMC5983MA_REG_XOUT0, raw, sizeof(raw));
429	  if (ret < 0)
430	    {
431	      return ret;
432	    }
433	
434	  *x = (int32_t)mmc5983ma_parse_axis(&raw[0], 6);
435	  *y = (int32_t)mmc5983ma_parse_axis(&raw[2], 4);
436	  *z = (int32_t)mmc5983ma_parse_axis(&raw[4], 2);
