475	                           FAR char *buffer, size_t buflen)
476	{
477	  FAR struct mmc5983ma_dev_s *priv = container_of(lower,
478	                                                  struct mmc5983ma_dev_s,
479	                                                  sensor_lower);
480	  struct sensor_mag mag;
481	  int32_t raw_x;
482	  int32_t raw_y;
483	  int32_t raw_z;
484	  int ret;
485	
486	  UNUSED(filep);
487	
488	  if (buflen != sizeof(mag))
489	    {
490	      return -EINVAL;
491	    }
492	
493	  ret = mmc5983ma_read_sample(priv, &raw_x, &raw_y, &raw_z, &mag.temperature);
494	  if (ret < 0)
495	    {
496	      return ret;
497	    }
498	
499	  mag.timestamp = sensor_get_timestamp();
500	  mag.x = mmc5983ma_raw_to_ut(raw_x);
501	  mag.y = mmc5983ma_raw_to_ut(raw_y);
502	  mag.z = mmc5983ma_raw_to_ut(raw_z);
503	  mmc5983ma_board_axes(&mag.x, &mag.y, &mag.z);
504	  mag.status = 0;
505	
506	  memcpy(buffer, &mag, sizeof(mag));
507	  return (int)sizeof(mag);
508	}
