159	static void bmi270_board_axes(FAR float *x, FAR float *y, FAR float *z)
160	{
161	  float cx = *x;
162	  float cy = *y;
163	
164	  *x = cy;
165	  *y = cx;
166	  *z = -(*z);
167	}
