169	/****************************************************************************
170	 * Name: bmi270_activate
171	 ****************************************************************************/
172	
173	static int bmi270_activate(FAR struct sensor_lowerhalf_s *lower,
174	                           FAR struct file *filep, bool enable)
175	{
176	  FAR struct bmi270_sensor_s     *priv  = NULL;
177	  FAR struct bmi270_sensor_dev_s *dev   = NULL;
178	  bool                            start = false;
179	  bool                            stop  = false;
180	  int                             ret   = OK;
181	  int                             tmp   = 0;
182	
183	  priv = (FAR struct bmi270_sensor_s *)lower;
184	  dev = priv->dev;
185	
186	  nxmutex_lock(&dev->lock);
187	
188	  tmp = (dev->priv[BMI270_ACCEL_IDX].enabled +
189	         dev->priv[BMI270_GYRO_IDX].enabled);
190	
191	  if (enable && tmp == 0)
192	    {
193	      /* One time start */
194	
195	      start = true;
196	    }
197	  else if (!enable && tmp == 1)
198	    {
199	      /* One time stop */
200	
201	      stop = true;
202	    }
203	
204	  priv->enabled = enable;
205	
206	  nxmutex_unlock(&dev->lock);
207	
208	  if (start)
209	    {
210	      /* Set normal mode */
211	
212	      bmi270_set_normal_imu(&priv->base);
213	
214	#ifdef CONFIG_BOARD_BMI270_POLL
215	      priv->last_update = sensor_get_timestamp();
216	
217	      /* Wake up the thread */
218	
219	      nxsem_post(&dev->run);
220	#endif
221	    }
222	
223	  else if (stop)
224	    {
225	      /* Disable acquisition of acc and gyro */
226	
227	      bmi270_putreg8(&priv->base, BMI270_PWR_CTRL, 0);
228	      nxsig_usleep(30000);
229	    }
230	
231	  return ret;
232	}
