257	
258	static int bmi270_fetch(FAR struct sensor_lowerhalf_s *lower,
259	                        FAR struct file *filep, FAR char *buffer,
260	                        size_t buflen)
261	{
262	  FAR struct bmi270_sensor_s *priv = NULL;
263	  int16_t                     data[3];
264	  int                         ret  = OK;
265	
266	  priv = (FAR struct bmi270_sensor_s *)lower;
267	
268	  switch (lower->type)
269	    {
270	      case SENSOR_TYPE_ACCELEROMETER:
271	        {
272	          struct sensor_accel accel;
273	
274	          bmi270_getregs(&priv->base, BMI270_DATA_8,
275	                         (FAR uint8_t *)data, 6);
276	
277	          accel.timestamp = sensor_get_timestamp();
278	          accel.x         = data[0] * priv->scale;
279	          accel.y         = data[1] * priv->scale;
280	          accel.z         = data[2] * priv->scale;
281	          bmi270_board_axes(&accel.x, &accel.y, &accel.z);
282	
283	          memcpy(buffer, &accel, sizeof(accel));
284	          ret = sizeof(accel);
285	
286	          break;
287	        }
288	
289	      case SENSOR_TYPE_GYROSCOPE:
290	        {
291	          struct sensor_gyro gyro;
292	
293	          bmi270_getregs(&priv->base, BMI270_DATA_14,
294	                         (FAR uint8_t *)data, 6);
295	
296	          gyro.timestamp = sensor_get_timestamp();
297	          gyro.x         = data[0] * priv->scale;
298	          gyro.y         = data[1] * priv->scale;
299	          gyro.z         = data[2] * priv->scale;
300	          bmi270_board_axes(&gyro.x, &gyro.y, &gyro.z);
301	
302	          memcpy(buffer, &gyro, sizeof(gyro));
303	          ret = sizeof(gyro);
304	
305	          break;
306	        }
307	
308	      default:
309	        {
310	          ret = -EINVAL;
311	          break;
312	        }
313	    }
314	
315	  return ret;
316	}
317	#endif
