361	/****************************************************************************
362	 * Name: bmi270_midpoint
363	 *
364	 * Description:
365	 *   Find the midpoint between two numbers.
366	 *
367	 ****************************************************************************/
368	
369	static uint32_t bmi270_midpoint(uint32_t a, uint32_t b)
370	{
371	  return (uint32_t)(((uint64_t)a +
372	                     (uint64_t)b + (uint64_t)1) / (uint64_t)2);
373	}
