375	/****************************************************************************
376	 * Name: bmi270_accel_scale
377	 ****************************************************************************/
378	
379	static int bmi270_accel_scale(FAR struct bmi270_sensor_s *priv,
380	                              uint8_t scale)
381	{
382	  int ret = OK;
383	
384	  if (scale < bmi270_midpoint(2, 4))
385	    {
386	      bmi270_putreg8(&priv->base, BMI270_ACC_RANGE, ACCEL_RANGE_2G);
387	      priv->scale = CONSTANTS_ONE_G / 16384.f;
388	    }
389	  else if (scale < bmi270_midpoint(4, 8))
390	    {
391	      bmi270_putreg8(&priv->base, BMI270_ACC_RANGE, ACCEL_RANGE_4G);
392	      priv->scale = CONSTANTS_ONE_G / 8192.f;
393	    }
394	  else if (scale < bmi270_midpoint(8, 16))
395	    {
396	      bmi270_putreg8(&priv->base, BMI270_ACC_RANGE, ACCEL_RANGE_8G);
397	      priv->scale = CONSTANTS_ONE_G / 4096.f;
398	    }
399	  else
400	    {
401	      bmi270_putreg8(&priv->base, BMI270_ACC_RANGE, ACCEL_RANGE_16G);
402	      priv->scale = CONSTANTS_ONE_G / 2048.f;
403	    }
404	
405	  return ret;
406	}
