408	/****************************************************************************
409	 * Name: bmi270_gyro_scale
410	 ****************************************************************************/
411	
412	static int bmi270_gyro_scale(FAR struct bmi270_sensor_s *priv,
413	                             uint16_t scale)
414	{
415	  int ret = OK;
416	
417	  if (scale < bmi270_midpoint(125, 250))
418	    {
419	      bmi270_putreg8(&priv->base, BMI270_GYR_RANGE, GYRO_RANGE_125);
420	      priv->scale = (M_PI / 180.0f) * 125.f / 32768.f;
421	    }
422	  else if (scale < bmi270_midpoint(250, 500))
423	    {
424	      bmi270_putreg8(&priv->base, BMI270_GYR_RANGE, GYRO_RANGE_250);
425	      priv->scale = (M_PI / 180.0f) * 250.f / 32768.f;
426	    }
427	  else if (scale < bmi270_midpoint(500, 1000))
428	    {
429	      bmi270_putreg8(&priv->base, BMI270_GYR_RANGE, GYRO_RANGE_500);
430	      priv->scale = (M_PI / 180.0f) * 500.f / 32768.f;
431	    }
432	  else if (scale < bmi270_midpoint(1000, 2000))
433	    {
434	      bmi270_putreg8(&priv->base, BMI270_GYR_RANGE, GYRO_RANGE_1000);
435	      priv->scale = (M_PI / 180.0f) * 1000.f / 32768.f;
436	    }
437	  else
438	    {
439	      bmi270_putreg8(&priv->base, BMI270_GYR_RANGE, GYRO_RANGE_2000);
440	      priv->scale = (M_PI / 180.0f) * 2000.f / 32768.f;
441	    }
442	
443	  return ret;
444	}
