525	/****************************************************************************
526	 * Name: bmi270_thread
527	 *
528	 * Description:
529	 *   Thread for performing interval measurement cycle and data read.
530	 *
531	 * Parameter:
532	 *   argc - Number opf arguments
533	 *   argv - Pointer to argument list
534	 *
535	 ****************************************************************************/
536	
537	static int bmi270_thread(int argc, FAR char **argv)
538	{
539	  FAR struct bmi270_sensor_dev_s *dev
540	      = (FAR struct bmi270_sensor_dev_s *)((uintptr_t)strtoul(argv[1], NULL,
541	                                                               16));
542	  FAR struct bmi270_sensor_s *accel = &dev->priv[BMI270_ACCEL_IDX];
543	  FAR struct bmi270_sensor_s *gyro  = &dev->priv[BMI270_GYRO_IDX];
544	  unsigned long               min_interval;
545	  int16_t                     data[6];
546	  int                         ret;
547	
548	  while (true)
549	    {
550	      if ((!accel->enabled) && (!gyro->enabled))
551	        {
552	          /* Waiting to be woken up */
553	
554	          ret = nxsem_wait(&dev->run);
555	          if (ret < 0)
556	            {
557	              continue;
558	            }
559	        }
560	
561	      /* Get data */
562	
563	      bmi270_getregs(&gyro->base, BMI270_DATA_8, (FAR uint8_t *)data, 12);
564	
565	      /* Read accel */
566	
567	      if (accel->enabled)
568	        {
569	          bmi270_accel_data(accel, data);
570	        }
571	
572	      /* Read gyro */
573	
574	      if (gyro->enabled)
575	        {
576	          bmi270_gyro_data(gyro, &data[3]);
577	        }
578	
579	      /* Sleeping thread before fetching the next sensor data */
580	
581	      min_interval = MIN(accel->interval, gyro->interval);
582	      nxsig_usleep(min_interval);
583	    }
584	
585	  return OK;
586	}
