592	
593	/****************************************************************************
594	 * Name: sf32lb52_bmi270_register
595	 *
596	 * Description:
597	 *   Register BMI270 accel/gyro as /dev/uorb/sensor_accelN and sensor_gyroN.
598	 *
599	 ****************************************************************************/
600	
601	int sf32lb52_bmi270_register(int devno, FAR struct i2c_master_s *i2c,
602	                             uint8_t addr)
603	{
604	  FAR struct bmi270_sensor_dev_s *dev = NULL;
605	  FAR struct bmi270_sensor_s     *tmp = NULL;
606	#ifdef CONFIG_BOARD_BMI270_POLL
607	  FAR char                       *argv[2];
608	  char                            arg1[32];
609	#endif
610	  int                             ret = OK;
611	
612	  g_bmi_i2c = i2c;
613	  g_bmi_addr = addr;
614	  g_bmi_devno = devno;
615	
616	  if (g_bmi_registered)
617	    {
618	      return OK;
619	    }
620	
621	  /* Initialize the device structure. */
622	
623	  dev = (FAR struct bmi270_sensor_dev_s *)kmm_malloc(sizeof(*dev));
624	  if (dev == NULL)
625	    {
626	      snerr("ERROR: Failed to allocate instance\n");
627	      return -ENOMEM;
628	    }
629	
630	  memset(dev, 0, sizeof(*dev));
631	  nxmutex_init(&dev->lock);
632	#ifdef CONFIG_BOARD_BMI270_POLL
633	  nxsem_init(&dev->run, 0, 0);
634	#endif
635	
636	  /* Accelerometer register */
637	
638	  tmp                = &dev->priv[BMI270_ACCEL_IDX];
639	  tmp->dev           = dev;
640	  tmp->base.i2c      = i2c;
641	  tmp->base.addr     = addr;
642	  tmp->base.freq     = CONFIG_BOARD_BMI270_I2C_FREQUENCY;
643	  tmp->lower.ops     = &g_sensor_ops;
644	  tmp->lower.type    = SENSOR_TYPE_ACCELEROMETER;
645	  tmp->lower.nbuffer = 1;
646	#ifdef CONFIG_BOARD_BMI270_POLL
647	  tmp->enabled       = false;
648	  tmp->interval      = CONFIG_BOARD_BMI270_POLL_INTERVAL;
649	#endif
650	
651	  /* Probe and init before uORB register (fail fast on wrong/missing device). */
652	
653	  ret = bmi270_checkid(&tmp->base);
654	  if (ret < 0)
655	    {
656	      snerr("BMI270 chip id check failed: %d\n", ret);
657	      goto err_free;
658	    }
659	
660	  ret = bmi270_init_seq(&tmp->base);
661	  if (ret < 0)
662	    {
663	      snerr("BMI270 init_seq failed: %d\n", ret);
664	      goto err_free;
665	    }
666	
667	  ret = sensor_register(&tmp->lower, devno);
668	  if (ret < 0)
669	    {
670	      snerr("sensor_register accel failed: %d\n", ret);
671	      goto err_free;
672	    }
673	
674	  /* Gyroscope register */
675	
676	  tmp                = &dev->priv[BMI270_GYRO_IDX];
677	  tmp->dev           = dev;
678	  tmp->base.i2c      = i2c;
679	  tmp->base.addr     = addr;
680	  tmp->base.freq     = CONFIG_BOARD_BMI270_I2C_FREQUENCY;
681	  tmp->lower.ops     = &g_sensor_ops;
682	  tmp->lower.type    = SENSOR_TYPE_GYROSCOPE;
683	  tmp->lower.nbuffer = 1;
684	#ifdef CONFIG_BOARD_BMI270_POLL
685	  tmp->enabled       = false;
686	  tmp->interval      = CONFIG_BOARD_BMI270_POLL_INTERVAL;
687	#endif
688	
689	  ret = sensor_register(&tmp->lower, devno);
690	  if (ret < 0)
691	    {
692	      snerr("sensor_register gyro failed: %d\n", ret);
693	      goto accel_err;
694	    }
695	
696	  /* Set default scale */
697	
698	  bmi270_accel_scale(&dev->priv[BMI270_ACCEL_IDX], 2);
699	  bmi270_gyro_scale(&dev->priv[BMI270_GYRO_IDX], 2000);
700	
701	#ifdef CONFIG_BOARD_BMI270_POLL
702	  /* Create thread for polling sensor data */
703	
704	  snprintf(arg1, 16, "%p", dev);
705	  argv[0] = arg1;
706	  argv[1] = NULL;
707	
708	  ret = kthread_create("bmi270_thread", SCHED_PRIORITY_DEFAULT,
709	                       CONFIG_BOARD_BMI270_THREAD_STACKSIZE,
710	                       bmi270_thread,
711	                       argv);
712	  if (ret < 0)
713	    {
714	      goto thr_err;
715	    }
716	#endif
717	
718	  g_bmi_dev = dev;
719	  g_bmi_registered = true;
720	  syslog(LOG_INFO, "bmi270: registered accel0/gyro0\n");
721	  return OK;
722	
723	#ifdef CONFIG_BOARD_BMI270_POLL
724	thr_err:
725	  sensor_unregister(&dev->priv[BMI270_GYRO_IDX].lower, devno);
726	#endif
727	accel_err:
728	  sensor_unregister(&dev->priv[BMI270_ACCEL_IDX].lower, devno);
729	err_free:
730	  kmm_free(dev);
731	  g_bmi_dev = NULL;
732	  g_bmi_registered = false;
733	
734	  return ret;
735	}
736	
737	int sf32lb52_bmi270_recover(void)
738	{
739	  int ret;
740	
741	  if (g_bmi_i2c == NULL)
742	    {
743	      syslog(LOG_ERR, "bmi270: recover skipped, bus unknown\n");
744	      return -ENODEV;
745	    }
746	
747	  if (!g_bmi_registered)
748	    {
749	      syslog(LOG_WARNING, "bmi270: recover register (was missing)\n");
750	      ret = sf32lb52_bmi270_register(g_bmi_devno, g_bmi_i2c, g_bmi_addr);
751	      if (ret < 0)
752	        {
753	          syslog(LOG_ERR, "bmi270: recover register failed: %d\n", ret);
754	        }
755	
756	      return ret;
757	    }
758	
759	  syslog(LOG_INFO, "bmi270: recover softreset + init_seq\n");
760	  bmi270_softreset(&g_bmi_dev->priv[BMI270_ACCEL_IDX].base);
761	  ret = bmi270_init_seq(&g_bmi_dev->priv[BMI270_ACCEL_IDX].base);
762	  if (ret < 0)
763	    {
764	      syslog(LOG_ERR, "bmi270: recover init_seq failed: %d\n", ret);
765	      return ret;
766	    }
767	
768	  bmi270_set_normal_imu(&g_bmi_dev->priv[BMI270_ACCEL_IDX].base);
769	  syslog(LOG_INFO, "bmi270: recover ok\n");
770	  return OK;
771	}
