1	/**
2	 * @file eta9184.c
3	 * @brief ETA9184：EN 默认关；STAT/DISCHRG/PULSE 用 GPIO 中断；4 秒窗口用独立软件定时器。
4	 *
5	 * 不要用 LPWORK work_queue 做周期任务：那会反复启动整条队列共用的
6	 * watchdog，系统节拍 10 ms 时容易把 g_wdactivelist 插坏（hardfault in
7	 * wd_insert）。窗口定时与按键一样用自己的 struct wdog_s + wd_start。
8	 *
9	 * SPDX-License-Identifier: Apache-2.0
10	 */
11	
12	#include <nuttx/config.h>
13	
14	#include <nuttx/clock.h>
15	#include <nuttx/irq.h>
16	#include <nuttx/wdog.h>
17	
18	#include <stdbool.h>
19	#include <stddef.h>
20	#include <stdint.h>
21	#include <string.h>
22	#include <syslog.h>
23	
24	#include "bf0_hal.h"
25	#include "drv_io.h"
26	#include "eta9184.h"
27	#include "sifli_gpio.h"
28	
29	#define ETA_STAT_PIN            GET_PIN_2(hwp_gpio1, 25) /**< PA25 STAT。 */
30	#define ETA_DISCHG_PIN          GET_PIN_2(hwp_gpio1, 24) /**< PA24 DISCHRG。 */
31	#define ETA_PULSE_PIN           GET_PIN_2(hwp_gpio1, 26) /**< PA26 PULSE。 */
32	#define ETA_EN_GPIO             28 /**< PA28 ENBST Boost。 */
33	
34	#define ETA_PULSE_DEBOUNCE_MS   20   /**< PULSE 上升沿去抖。 */
35	#define ETA_EDGE_DEBOUNCE_MS    5    /**< STAT/DISCHRG 边沿去抖。 */
36	#define ETA_WINDOW_MS           4000 /**< 电量统计窗口。 */
37	#define ETA_DISCHG_LOW_EDGES    6    /**< 低电量 DISCHRG 边沿阈值。 */
38	
39	static bool g_inited;                          /**< 是否已 eta9184_init。 */
40	static volatile bool g_running;                /**< 采样是否在运行。 */
41	static bool g_irq_on;                          /**< GPIO 中断是否已使能。 */
42	static bool g_boost_on;                        /**< Boost 软件开关。 */
43	static volatile bool g_stat_high;              /**< STAT 最近稳定电平。 */
44	static volatile bool g_dischg_high;            /**< DISCHRG 最近稳定电平。 */
45	static volatile bool g_pulse_high;             /**< PULSE 窗口结束时电平。 */
46	static volatile int g_pulse_count;             /**< 当前窗口 PULSE 次数。 */
47	static volatile int g_dischg_edges;            /**< 当前窗口 DISCHRG 边沿数。 */
48	static volatile int g_bat_level;               /**< 0 未知，1～4 四分位，5 满。 */
49	static volatile int g_dischg_status;           /**< DISCHRG 细粒度状态。 */
50	static volatile int g_chg_status;              /**< STAT 细粒度状态。 */
51	static volatile bool g_full_edge;             /**< 刚进入充满，待 VBATS 校准。 */
52	static volatile unsigned int g_timer_ticks;    /**< 4 秒软件定时器次数。 */
53	static volatile unsigned int g_pulse_edges;    /**< 累计 PULSE 上升沿。 */
54	static volatile unsigned int g_dischg_edge_total; /**< 累计 DISCHRG 边沿。 */
55	static volatile unsigned int g_windows;        /**< 已完成 4 秒窗口数。 */
56	static volatile clock_t g_last_pulse_tick;     /**< 上次接受的 PULSE 沿。 */
57	static volatile clock_t g_last_dischg_tick;    /**< 上次接受的 DISCHRG 沿。 */
58	static volatile clock_t g_last_stat_tick;      /**< 上次接受的 STAT 沿。 */
59	static struct wdog_s g_wdog;                   /**< 独立 4 秒软件定时器。 */
60	
61	/** @brief 读 ETA9184 GPIO 原始电平。 */
62	static bool eta_gpio_high(uint32_t pin)
63	{
64	  return sifli_gpio_read(pin);
65	}
66	
67	/** @brief 配置上拉并 mux ETA9184 状态脚。 */
68	static void eta_status_pullup(void)
69	{
70	  HAL_PIN_Set(PAD_PA24, GPIO_A24, PIN_PULLUP, 1);
71	  HAL_PIN_Set(PAD_PA25, GPIO_A25, PIN_PULLUP, 1);
72	  HAL_PIN_Set(PAD_PA26, GPIO_A26, PIN_PULLUP, 1);
73	}
74	
75	/** @brief 根据当前电平更新充放电细粒度状态。 */
76	static void eta_apply_charge_discharge(void)
77	{
78	  if (g_dischg_edges >= ETA_DISCHG_LOW_EDGES)
79	    {
80	      g_dischg_status = ETA9184_DISCHG_LOW;
81	    }
82	  else if (!g_dischg_high)
83	    {
84	      g_dischg_status = ETA9184_DISCHG_ON;
85	    }
86	  else
87	    {
88	      g_dischg_status = ETA9184_DISCHG_OFF;
89	    }
90	
91	  if (!g_stat_high)
92	    {
93	      g_chg_status = ETA9184_CHG_CHARGING;
94	      g_full_edge = false;
95	    }
96	  else if (g_dischg_high)
97	    {
98	      /* 只在充电→充满边沿校准。开机/空闲时 STAT 高+DISCHRG 高与充满相同，
99	       * 若当边沿会把当前电压（可能已是 3.98 V）写成 100%。 */
100	      if (g_chg_status == ETA9184_CHG_CHARGING)
101	        {
102	          g_full_edge = true;
103	        }
104	
105	      g_chg_status = ETA9184_CHG_FULL;
106	    }
107	  else
108	    {
109	      g_chg_status = ETA9184_CHG_IDLE;
110	      g_full_edge = false;
111	    }
112	}
113	
114	/** @brief 4 秒窗口结束：映射 PULSE 次数为 bat_level。ISR 可调用。 */
115	static void eta_cycle_end(void)
116	{
117	  int count = g_pulse_count;
118	  bool held_high;
119	
120	  g_pulse_high = eta_gpio_high(ETA_PULSE_PIN);
121	  g_stat_high = eta_gpio_high(ETA_STAT_PIN);
122	  g_dischg_high = eta_gpio_high(ETA_DISCHG_PIN);
123	
124	  held_high = (count == 0 && g_pulse_high);
125	
126	  if (held_high || count >= 4)
127	    {
128	      g_bat_level = 5;
129	    }
130	  else if (count >= 1)
131	    {
132	      g_bat_level = count;
133	    }
134	
135	  g_pulse_count = 0;
136	  g_dischg_edges = 0;
137	  g_windows++;
138	  g_timer_ticks++;
139	  eta_apply_charge_discharge();
140	}
141	
142	/** @brief 独立软件定时器到期：关窗口并再开 4 秒。 */
143	static void eta_window_cb(wdparm_t arg)
144	{
145	  UNUSED(arg);
146	
147	  eta_cycle_end();
148	
149	  if (g_running)
150	    {
151	      (void)wd_start(&g_wdog, MSEC2TICK(ETA_WINDOW_MS), eta_window_cb, 0);
152	    }
153	}
154	
155	/** @brief 距上次边沿的滴答；回退则视为 0，避免去抖失效。 */
156	static clock_t eta_tick_age(clock_t now, clock_t last)
157	{
158	  clock_t dt = now - last;
159	
160	  if (dt > ((clock_t)-1 / 2))
161	    {
162	      return 0;
163	    }
164	
165	  return dt;
166	}
167	
168	/** @brief PA26 上升沿：计一次电量脉冲。 */
169	static void eta_pulse_isr(void *arg)
170	{
171	  clock_t now = clock_systime_ticks();
172	
173	  UNUSED(arg);
174	  if (eta_tick_age(now, g_last_pulse_tick) < MSEC2TICK(ETA_PULSE_DEBOUNCE_MS))
175	    {
176	      return;
177	    }
178	
179	  g_last_pulse_tick = now;
180	  g_pulse_count++;
181	  g_pulse_edges++;
182	}
183	
184	/** @brief PA24 双沿：计 DISCHRG 翻转（低电约 1 Hz）。 */
185	static void eta_dischg_isr(void *arg)
186	{
187	  clock_t now = clock_systime_ticks();
188	
189	  UNUSED(arg);
190	  if (eta_tick_age(now, g_last_dischg_tick) < MSEC2TICK(ETA_EDGE_DEBOUNCE_MS))
191	    {
192	      return;
193	    }
194	
195	  g_last_dischg_tick = now;
196	  g_dischg_edges++;
197	  g_dischg_edge_total++;
198	  g_dischg_high = eta_gpio_high(ETA_DISCHG_PIN);
199	  eta_apply_charge_discharge();
200	}
201	
202	/** @brief PA25 双沿：充电 STAT。 */
203	static void eta_stat_isr(void *arg)
204	{
205	  clock_t now = clock_systime_ticks();
206	
207	  UNUSED(arg);
208	  if (eta_tick_age(now, g_last_stat_tick) < MSEC2TICK(ETA_EDGE_DEBOUNCE_MS))
209	    {
210	      return;
211	    }
212	
213	  g_last_stat_tick = now;
214	  g_stat_high = eta_gpio_high(ETA_STAT_PIN);
215	  eta_apply_charge_discharge();
216	}
217	
218	/** @brief 使能或关闭状态脚外部中断。 */
219	static int eta_irq_set(bool enable)
220	{
221	  int ret;
222	
223	  if (enable == g_irq_on)
224	    {
225	      return 0;
226	    }
227	
228	  if (!enable)
229	    {
230	      (void)sifli_gpio_set_event(ETA_PULSE_PIN, false, false, NULL, NULL);
231	      (void)sifli_gpio_set_event(ETA_DISCHG_PIN, false, false, NULL, NULL);
232	      (void)sifli_gpio_set_event(ETA_STAT_PIN, false, false, NULL, NULL);
233	      g_irq_on = false;
234	      return 0;
235	    }
236	
237	  ret = sifli_gpio_set_event(ETA_PULSE_PIN, true, false,
238	                             eta_pulse_isr, NULL);
239	  if (ret < 0)
240	    {
241	      syslog(LOG_ERR, "eta9184: PULSE irq failed: %d\n", ret);
242	      return ret;
243	    }
244	
245	  ret = sifli_gpio_set_event(ETA_DISCHG_PIN, true, true,
246	                             eta_dischg_isr, NULL);
247	  if (ret < 0)
248	    {
249	      (void)sifli_gpio_set_event(ETA_PULSE_PIN, false, false, NULL, NULL);
250	      syslog(LOG_ERR, "eta9184: DISCHRG irq failed: %d\n", ret);
251	      return ret;
252	    }
253	
254	  ret = sifli_gpio_set_event(ETA_STAT_PIN, true, true,
255	                             eta_stat_isr, NULL);
256	  if (ret < 0)
257	    {
258	      (void)sifli_gpio_set_event(ETA_PULSE_PIN, false, false, NULL, NULL);
259	      (void)sifli_gpio_set_event(ETA_DISCHG_PIN, false, false, NULL, NULL);
260	      syslog(LOG_ERR, "eta9184: STAT irq failed: %d\n", ret);
261	      return ret;
262	    }
263	
264	  g_irq_on = true;
265	  return 0;
266	}
267	
268	/** @brief 从当前 GPIO 采样并复位边沿去抖。 */
269	static void eta_level_reset(void)
270	{
271	  irqstate_t flags;
272	  clock_t now;
273	
274	  g_stat_high = eta_gpio_high(ETA_STAT_PIN);
275	  g_dischg_high = eta_gpio_high(ETA_DISCHG_PIN);
276	  g_pulse_high = eta_gpio_high(ETA_PULSE_PIN);
277	
278	  now = clock_systime_ticks();
279	  flags = up_irq_save();
280	  g_last_pulse_tick = now;
281	  g_last_dischg_tick = now;
282	  g_last_stat_tick = now;
283	  up_irq_restore(flags);
284	}
