336	/**
337	 * @brief 取出并清除“刚进入充满”边沿。
338	 */
339	bool eta9184_take_full_edge(void)
340	{
341	  irqstate_t flags;
342	  bool edge;
343	
344	  flags = up_irq_save();
345	  edge = g_full_edge;
346	  g_full_edge = false;
347	  up_irq_restore(flags);
348	  return edge;
