351	/**
352	 * @brief 读取充电 / 放电 / 低电量 / 空闲。
353	 */
354	enum eta9184_power_e eta9184_power_state(void)
355	{
356	  if (g_chg_status == ETA9184_CHG_CHARGING)
357	    {
358	      return ETA9184_POWER_CHARGING;
359	    }
360	
361	  if (g_dischg_status == ETA9184_DISCHG_LOW)
362	    {
363	      return ETA9184_POWER_LOW;
364	    }
365	
366	  if (g_dischg_status == ETA9184_DISCHG_ON)
367	    {
368	      return ETA9184_POWER_DISCHARGING;
369	    }
370	
371	  return ETA9184_POWER_IDLE;
372	}
373	
374	/**
375	 * @brief 复制当前采样快照。
376	 */
377	void eta9184_get_status(FAR struct eta9184_status_s *out)
378	{
379	  irqstate_t flags;
380	
381	  if (out == NULL)
382	    {
383	      return;
384	    }
385	
386	  flags = up_irq_save();
387	  out->chrg_high = eta_gpio_high(ETA_STAT_PIN);
388	  out->stat_high = eta_gpio_high(ETA_DISCHG_PIN);
389	  out->pulse_high = eta_gpio_high(ETA_PULSE_PIN);
390	  out->boost_on = g_boost_on;
391	  out->bat_level = g_bat_level;
392	  out->pulse_count = g_pulse_count;
393	  out->dischg_edges = g_dischg_edges;
394	  out->timer_ticks = g_timer_ticks;
395	  out->pulse_irqs = g_pulse_edges;
396	  out->dischg_irqs = g_dischg_edge_total;
397	  out->windows = g_windows;
398	  out->chg = (enum eta9184_chg_e)g_chg_status;
399	  out->dischg = (enum eta9184_dischg_e)g_dischg_status;
400	  out->power = eta9184_power_state();
401	  up_irq_restore(flags);
402	
403	  out->bat_pct = -1;
404	  out->pulse_pct = eta9184_battery_percent();
405	  out->pulse_trusted = false;
406	}
