408	/**
409	 * @brief 配置引脚，Boost / EN 默认关。不上报电量。
410	 *
411	 * @return 0 成功，负值为错误码。
412	 */
413	int eta9184_init(void)
414	{
415	  if (g_inited)
416	    {
417	      return 0;
418	    }
419	
420	  eta_status_pullup();
421	  sifli_gpio_config(ETA_STAT_PIN, GPIO_INPUT);
422	  sifli_gpio_config(ETA_DISCHG_PIN, GPIO_INPUT);
423	  sifli_gpio_config(ETA_PULSE_PIN, GPIO_INPUT);
424	  eta9184_boost_set(false);
425	
426	  memset(&g_wdog, 0, sizeof(g_wdog));
427	  eta_level_reset();
428	  g_pulse_count = 0;
429	  g_dischg_edges = 0;
430	  g_bat_level = 0;
431	  g_chg_status = ETA9184_CHG_IDLE;
432	  g_dischg_status = ETA9184_DISCHG_OFF;
433	  eta_apply_charge_discharge();
434	  g_timer_ticks = 0;
435	  g_pulse_edges = 0;
436	  g_dischg_edge_total = 0;
437	  g_windows = 0;
438	  g_irq_on = false;
439	  g_running = false;
440	  g_inited = true;
441	  syslog(LOG_INFO, "eta9184: STAT=PA25 DISCHRG=PA24 PULSE=PA26 EN=off\n");
442	  return 0;
443	}
444	
445	/**
446	 * @brief 挂 GPIO 中断，启动 4 秒软件定时器。不改 Boost。
447	 *
448	 * @return 0 成功，负值为错误码。
449	 */
450	int eta9184_start(void)
451	{
452	  int ret;
453	
454	  ret = eta9184_init();
455	  if (ret < 0)
456	    {
457	      return ret;
458	    }
459	
460	  if (g_running)
461	    {
462	      return 0;
463	    }
464	
465	  eta_status_pullup();
466	  eta_level_reset();
467	  eta_apply_charge_discharge();
468	  g_pulse_count = 0;
469	  g_dischg_edges = 0;
470	  g_timer_ticks = 0;
471	  g_pulse_edges = 0;
472	  g_dischg_edge_total = 0;
473	  g_windows = 0;
474	
475	  ret = eta_irq_set(true);
476	  if (ret < 0)
477	    {
478	      return ret;
479	    }
480	
481	  g_running = true;
482	  ret = wd_start(&g_wdog, MSEC2TICK(ETA_WINDOW_MS), eta_window_cb, 0);
483	  if (ret < 0)
484	    {
485	      g_running = false;
486	      syslog(LOG_ERR, "eta9184: window timer start failed: %d\n", ret);
487	      return ret;
488	    }
489	
490	  syslog(LOG_INFO, "eta9184: sampling (GPIO irq + 4s wdog, EN %s)\n",
491	         g_boost_on ? "on" : "off");
492	  return 0;
493	}
494	
495	/**
496	 * @brief 停止 4 秒软件定时器。不关 EN。
497	 */
498	void eta9184_stop(void)
499	{
500	  if (!g_running)
501	    {
502	      return;
503	    }
504	
505	  g_running = false;
506	  wd_cancel(&g_wdog);
507	}
