1	/**
2	 * @file sf32lb52_buttons.c
3	 * @brief 自行车 UI 按键 lower-half：KEY1=PA30、KEY2=PA33、PWR=PA34。
4	 *
5	 * KEY1/KEY2 上拉按下接地；PWR 下拉按下为高（开机键，硬件 10s 复位）。
6	 * 注册 /dev/buttons。只由板级线程 10 ms 读 GPIO，不上边沿中断、
7	 * 不挂 NuttX 软件 wdog。
8	 *
9	 * SPDX-License-Identifier: Apache-2.0
10	 */
11	
12	#include <nuttx/config.h>
13	
14	#include <stdbool.h>
15	#include <stdint.h>
16	#include <errno.h>
17	#include <unistd.h>
18	
19	#include <nuttx/input/buttons.h>
20	#include <nuttx/kthread.h>
21	#include <nuttx/sched.h>
22	
23	#include "sifli_gpio.h"
24	#include "sf32lb52_buttons.h"
25	
26	#ifdef CONFIG_INPUT_BUTTONS
27	
28	#define SF32LB52_BTN_CLICK_PIN   GET_PIN_2(hwp_gpio1, 33) /**< KEY2 PA33，bit0。 */
29	#define SF32LB52_BTN_SCROLL_PIN  GET_PIN_2(hwp_gpio1, 30) /**< KEY1 PA30，bit1。 */
30	#define SF32LB52_BTN_PWR_PIN     GET_PIN_2(hwp_gpio1, 34) /**< PWR PA34，bit2。 */
31	#define SF32LB52_BTN_CLICK_BIT   0  /**< KEY2 位掩码下标。 */
32	#define SF32LB52_BTN_SCROLL_BIT  1  /**< KEY1 位掩码下标。 */
33	#define SF32LB52_BTN_PWR_BIT     2  /**< PWR 位掩码下标。 */
34	#define SF32LB52_BTN_ACTIVE_HIGH 0  /**< KEY1/KEY2：0=上拉按下为低。 */
35	#define SF32LB52_BUTTON_POLL_MS  10 /**< 轮询周期（毫秒）。 */
36	#define SF32LB52_BUTTON_POLL_PRIO 50
37	#define SF32LB52_BUTTON_POLL_STACK 1536
38	
39	static uint8_t g_btn_poll_stack[SF32LB52_BUTTON_POLL_STACK]
40	    __attribute__((aligned(16)));
41	
42	/** @brief 按键 lower-half 私有状态。 */
43	struct sf32lb52_btnlower_s {
44	    struct btn_lowerhalf_s lower;
45	    btn_handler_t handler;       /**< NuttX 上报回调。 */
46	    FAR void *arg;               /**< 回调参数。 */
47	    volatile bool poll_enabled;  /**< 轮询线程是否采样。 */
48	    int poll_tid;                /**< 轮询线程 pid，0 表示未创建。 */
49	    btn_buttonset_t last_sample; /**< 上次采样位图。 */
50	};
51	
52	static btn_buttonset_t sf32lb52_btn_supported(
53	    FAR const struct btn_lowerhalf_s *lower);
54	static btn_buttonset_t sf32lb52_btn_buttons(
55	    FAR const struct btn_lowerhalf_s *lower);
56	static void sf32lb52_btn_enable(FAR const struct btn_lowerhalf_s *lower,
57	                                btn_buttonset_t press,
58	                                btn_buttonset_t release,
59	                                btn_handler_t handler,
60	                                FAR void *arg);
61	
62	/** 全局按键 lower-half 单例。 */
63	static struct sf32lb52_btnlower_s g_btnlower = {
64	    {
65	        sf32lb52_btn_supported,
66	        sf32lb52_btn_buttons,
67	        sf32lb52_btn_enable,
68	        NULL,
69	    },
70	    NULL,
71	    NULL,
72	    false,
73	    0,
74	    0,
75	};
76	
77	/** @brief 读取当前按键位图。 */
78	static btn_buttonset_t sf32lb52_button_readset(void)
79	{
80	    btn_buttonset_t set = 0;
81	    bool click = sifli_gpio_read(SF32LB52_BTN_CLICK_PIN);
82	    bool scroll = sifli_gpio_read(SF32LB52_BTN_SCROLL_PIN);
83	    bool pwr = sifli_gpio_read(SF32LB52_BTN_PWR_PIN);
84	
85	#if SF32LB52_BTN_ACTIVE_HIGH
86	    if (click) {
87	        set |= (1u << SF32LB52_BTN_CLICK_BIT);
88	    }
89	    if (scroll) {
90	        set |= (1u << SF32LB52_BTN_SCROLL_BIT);
91	    }
92	#else
93	    if (!click) {
94	        set |= (1u << SF32LB52_BTN_CLICK_BIT);
95	    }
96	    if (!scroll) {
97	        set |= (1u << SF32LB52_BTN_SCROLL_BIT);
98	    }
99	#endif
100	
101	    /* PWR_KEY_READ：按下为高。 */
102	    if (pwr) {
103	        set |= (1u << SF32LB52_BTN_PWR_BIT);
104	    }
105	
106	    return set;
107	}
108	
109	/** @brief 状态变化则通知 upper-half。 */
110	static void sf32lb52_button_notify(FAR struct sf32lb52_btnlower_s *priv)
111	{
112	    btn_buttonset_t sample;
113	    btn_handler_t handler;
114	
115	    sample = sf32lb52_button_readset();
116	    if (sample == priv->last_sample) {
117	        return;
118	    }
119	
120	    priv->last_sample = sample;
121	    handler = priv->handler;
122	    if (handler != NULL) {
123	        handler(&priv->lower, priv->arg);
124	    }
125	}
126	
127	/** @brief 板级轮询线程：只在线程上下文读键。 */
128	static int sf32lb52_button_poll_task(int argc, FAR char *argv[])
129	{
130	    FAR struct sf32lb52_btnlower_s *priv = &g_btnlower;
131	
132	    (void)argc;
133	    (void)argv;
134	
135	    for (;;) {
136	        if (priv->poll_enabled) {
137	            sf32lb52_button_notify(priv);
138	        }
139	
140	        usleep(SF32LB52_BUTTON_POLL_MS * 1000);
141	    }
142	
143	    return 0;
144	}
145	
146	/** @brief 返回支持的按键位掩码。 */
147	static btn_buttonset_t sf32lb52_btn_supported(
148	    FAR const struct btn_lowerhalf_s *lower)
149	{
150	    (void)lower;
151	    return (1u << SF32LB52_BTN_CLICK_BIT) |
152	           (1u << SF32LB52_BTN_SCROLL_BIT) |
153	           (1u << SF32LB52_BTN_PWR_BIT);
154	}
155	
156	/** @brief 返回当前按下的按键位。 */
157	static btn_buttonset_t sf32lb52_btn_buttons(
158	    FAR const struct btn_lowerhalf_s *lower)
159	{
160	    (void)lower;
161	    return sf32lb52_button_readset();
162	}
163	
164	/** @brief 使能/禁用轮询并挂接 handler。 */
165	static void sf32lb52_btn_enable(FAR const struct btn_lowerhalf_s *lower,
166	                                btn_buttonset_t press,
167	                                btn_buttonset_t release,
168	                                btn_handler_t handler,
169	                                FAR void *arg)
170	{
171	    FAR struct sf32lb52_btnlower_s *priv = (FAR struct sf32lb52_btnlower_s *)lower;
172	    btn_buttonset_t either = press | release;
173	    int ret;
174	
175	    if (either == 0 || handler == NULL) {
176	        priv->poll_enabled = false;
177	        priv->handler = NULL;
178	        priv->arg = NULL;
179	        return;
180	    }
181	
182	    priv->handler = handler;
183	    priv->arg = arg;
184	    priv->last_sample = sf32lb52_button_readset();
185	    priv->poll_enabled = true;
186	
187	    if (priv->poll_tid <= 0) {
188	        ret = kthread_create_with_stack("btn_poll",
189	                                        SF32LB52_BUTTON_POLL_PRIO,
190	                                        g_btn_poll_stack,
191	                                        sizeof(g_btn_poll_stack),
192	                                        sf32lb52_button_poll_task, NULL);
193	        if (ret > 0) {
194	            priv->poll_tid = ret;
195	        }
196	    }
197	}
198	
199	/**
200	 * @brief 初始化 PA30/PA33/PA34 并注册 /dev/buttons。
201	 * @param devname 字符设备路径。
202	 * @return 0 成功，负值为 btn_register 错误码。
203	 */
204	int sf32lb52_button_initialize(FAR const char *devname)
205	{
206	    int ret;
207	
208	    sifli_gpio_config(SF32LB52_BTN_CLICK_PIN, GPIO_INPUT);
209	    sifli_gpio_config(SF32LB52_BTN_SCROLL_PIN, GPIO_INPUT);
210	    sifli_gpio_config(SF32LB52_BTN_PWR_PIN, GPIO_INPUT);
211	
212	    ret = btn_register(devname, &g_btnlower.lower);
213	    if (ret < 0) {
214	        return ret;
215	    }
216	
217	    return OK;
218	}
