220	/**
221	 * @brief 调试直读按键原始电平（不经 debounce）。
222	 * @param[out] click  KEY2 PA33 逻辑按下（1=按下），可 NULL。
223	 * @param[out] scroll KEY1 PA30 逻辑按下（1=按下），可 NULL。
224	 * @param[out] pwr    PWR PA34 逻辑按下（1=按下），可 NULL。
225	 */
226	void sf32lb52_button_debug_read(bool *click, bool *scroll, bool *pwr)
227	{
228	    bool c = sifli_gpio_read(SF32LB52_BTN_CLICK_PIN);
229	    bool s = sifli_gpio_read(SF32LB52_BTN_SCROLL_PIN);
230	    bool p = sifli_gpio_read(SF32LB52_BTN_PWR_PIN);
231	
232	#if SF32LB52_BTN_ACTIVE_HIGH
233	    if (click != NULL) {
234	        *click = c;
235	    }
236	    if (scroll != NULL) {
237	        *scroll = s;
238	    }
239	#else
240	    if (click != NULL) {
241	        *click = !c;
242	    }
243	    if (scroll != NULL) {
244	        *scroll = !s;
245	    }
246	#endif
247	
248	    if (pwr != NULL) {
249	        *pwr = p;
250	    }
251	}
