165	    for (i = 0; i < cnt; i++) {
166	        lv_obj_t *child = lv_obj_get_child(obj, i);
167	
168	        if (lv_port_is_focus_candidate(child) &&
169	            !lv_port_has_focus_candidate_child(child)) {
170	            return true;
171	        }
172	
173	        if (lv_port_has_focus_candidate_child(child)) {
174	            return true;
