247	    }
248	
249	    if (s_ctx.focus_count == 0) {
250	        s_ctx.focused = NULL;
251	        s_ctx.focus_index = -1;
252	        s_ctx.focus_ready = false;
253	        return;
254	    }
255	
256	    if (index < 0) {
257	        index = 0;
258	    }
259	    if ((uint32_t)index >= s_ctx.focus_count) {
260	        index = (int)s_ctx.focus_count - 1;
261	    }
262	
263	    s_ctx.focus_index = index;
264	    s_ctx.focused = s_ctx.focus_items[index];
265	    lv_obj_add_state(s_ctx.focused, LV_STATE_FOCUSED);
266	    s_ctx.focus_ready = true;
267	}
