269	static void lv_port_focus_sync(void)
270	{
271	    lv_obj_t *scr;
272	    lv_obj_t *prev = s_ctx.focused;
273	    uint32_t n = 0;
274	    uint32_t i;
275	    int keep_index = -1;
276	
277	    scr = lv_screen_active();
278	    if (scr == NULL) {
279	        s_ctx.focus_count = 0;
280	        s_ctx.focus_ready = false;
281	        s_ctx.focused = NULL;
282	        return;
283	    }
284	
285	    lv_port_collect_nav_buttons(scr, &n);
286	    s_ctx.focus_count = n;
287	
288	    if (prev != NULL) {
289	        for (i = 0; i < n; i++) {
290	            if (s_ctx.focus_items[i] == prev) {
291	                keep_index = (int)i;
292	                break;
293	            }
294	        }
295	    }
296	
297	    if (n == 0) {
298	        if (prev != NULL) {
299	            lv_obj_clear_state(prev, LV_STATE_FOCUSED);
300	        }
301	        s_ctx.focused = NULL;
302	        s_ctx.focus_index = -1;
303	        s_ctx.focus_ready = false;
304	        return;
305	    }
306	
307	    if (keep_index < 0) {
308	        keep_index = 0;
309	    }
310	
311	    lv_port_focus_apply(keep_index);
312	}
313	
314	static void lv_port_focus_prepare(void)
315	{
316	    if (!s_ctx.focus_ready || !lv_port_focus_still_valid()) {
317	        lv_port_focus_sync();
318	    }
319	}
