328	    }
329	
330	    next = s_ctx.focus_index + 1;
331	    if ((uint32_t)next >= s_ctx.focus_count) {
332	        next = 0;
333	    }
334	
335	    lv_port_focus_apply(next);
336	    LV_LOG_USER("btn: focus next");
337	}
