538	static void lv_port_btn_timer(lv_timer_t *timer)
539	{
540	    btn_buttonset_t set;
541	    lv_obj_t *mbox;
542	#if MYVENDOR_LVGL_STALL_LOG
543	    uint32_t now;
544	    uint32_t gap;
545	#endif
546	
547	    LV_UNUSED(timer);
548	
549	    if (s_ctx.fd < 0) {
550	        return;
551	    }
552	
553	    if (helm_pwr_is_offing()) {
554	        s_ctx.last = lv_port_btn_read();
555	        return;
556	    }
557	
558	#if MYVENDOR_LVGL_STALL_LOG
559	    now = lv_tick_get();
560	    gap = s_btn_last_poll_tick ? lv_tick_elaps(s_btn_last_poll_tick) : 0;
561	    s_btn_last_poll_tick = now;
562	    if (gap > 80u) {
563	        LVGL_STALL("btn timer gap %ums scroll_cb=%d confirm_cb=%d",
564	            (unsigned)gap, s_ctx.page_scroll_cb != NULL,
565	            s_ctx.page_confirm_cb != NULL);
566	    }
567	#endif
568	
569	    set = lv_port_btn_read();
570	    mbox = lv_port_get_active_msgbox();
571	
572	    /* CPU load is a 1-2 second history and cannot predict the first frame
573	     * after input.  Raise the short interactive floor on both edges so a
574	     * long press release also has a fresh window for its UI callback. */
575	    if (((set ^ s_ctx.last) &
576	         (LV_PORT_BTN_SCROLL | LV_PORT_BTN_CLICK | LV_PORT_BTN_PWR)) != 0) {
577	        sf32lb_dvfs_interact();
578	    }
579	
580	    if (helm_idle_is_sleeping()) {
581	        if ((set & ~s_ctx.last) != 0) {
582	            helm_idle_wake();
583	            s_ctx.idle_swallow = true;
584	        }
585	
586	        if (s_ctx.idle_swallow) {
587	            if (set == 0) {
588	                s_ctx.idle_swallow = false;
589	            }
590	
591	            s_ctx.last = set;
592	            return;
593	        }
594	    } else {
595	        s_ctx.idle_swallow = false;
596	    }
597	
598	    if (s_ctx.had_msgbox && mbox == NULL) {
599	        s_ctx.focus_ready = false;
600	    }
601	    s_ctx.had_msgbox = (mbox != NULL);
602	
603	    if ((set & LV_PORT_BTN_SCROLL) && !(s_ctx.last & LV_PORT_BTN_SCROLL)) {
604	        s_ctx.scroll_press_tick = lv_tick_get();
605	        s_ctx.scroll_long_fired = false;
606	        myvendor_sound_key();
607	        BTN_LOG("KEY1 down set=0x%02x scroll_cb=%d", (unsigned)set,
608	            s_ctx.page_scroll_cb != NULL);
609	    }
610	
611	    if ((set & LV_PORT_BTN_SCROLL) && (s_ctx.last & LV_PORT_BTN_SCROLL)) {
612	        lv_port_scroll_hold_update();
613	    }
614	
615	    if (!(set & LV_PORT_BTN_SCROLL) && (s_ctx.last & LV_PORT_BTN_SCROLL)) {
616	        BTN_LOG("KEY1 up%s set=0x%02x",
617	                s_ctx.scroll_long_fired ? " after-long" : "",
618	                (unsigned)set);
619	        if (!s_ctx.scroll_long_fired) {
620	            lv_port_scroll_down();
621	        }
622	        s_ctx.scroll_long_fired = false;
623	    }
624	
625	    if ((set & LV_PORT_BTN_CLICK) && !(s_ctx.last & LV_PORT_BTN_CLICK)) {
626	        s_ctx.click_press_tick = lv_tick_get();
627	        s_ctx.click_long_fired = false;
628	        myvendor_sound_ok();
629	        BTN_LOG("KEY2 down set=0x%02x confirm_cb=%d", (unsigned)set,
630	            s_ctx.page_confirm_cb != NULL);
631	    }
632	
633	    if ((set & LV_PORT_BTN_CLICK) && (s_ctx.last & LV_PORT_BTN_CLICK)) {
634	        lv_port_click_hold_update();
635	    }
636	
637	    if (!(set & LV_PORT_BTN_CLICK) && (s_ctx.last & LV_PORT_BTN_CLICK)) {
638	        BTN_LOG("KEY2 up%s set=0x%02x",
639	                s_ctx.click_long_fired ? " after-long" : "",
640	                (unsigned)set);
641	        if (s_ctx.click_long_fired) {
642	            if (s_ctx.page_longpress2_up_cb != NULL) {
643	                s_ctx.page_longpress2_up_cb(s_ctx.page_longpress2_up_ud);
644	            }
645	        } else {
646	            lv_port_click_confirm();
647	        }
648	        s_ctx.click_long_fired = false;
649	    }
650	
651	    if ((set & LV_PORT_BTN_PWR) && !(s_ctx.last & LV_PORT_BTN_PWR)) {
652	        s_ctx.pwr_press_tick = lv_tick_get();
653	        s_ctx.pwr_long_fired = false;
654	        myvendor_sound_key();
655	        BTN_LOG("PWR down set=0x%02x", (unsigned)set);
656	    }
657	
658	    if ((set & LV_PORT_BTN_PWR) && (s_ctx.last & LV_PORT_BTN_PWR)) {
659	        lv_port_pwr_hold_update();
660	    }
661	
662	    if (!(set & LV_PORT_BTN_PWR) && (s_ctx.last & LV_PORT_BTN_PWR)) {
663	        BTN_LOG("PWR up%s set=0x%02x",
664	                s_ctx.pwr_long_fired ? " after-long" : "",
665	                (unsigned)set);
666	        if (!s_ctx.pwr_long_fired) {
667	            helm_pwr_on_click();
668	        }
669	        s_ctx.pwr_long_fired = false;
670	    }
671	
672	    s_ctx.last = set;
673	}
