706	     * long-press (home KEY1 long = menu, menu KEY1 long = back). */
707	    if (s_ctx.last & LV_PORT_BTN_SCROLL) {
708	        s_ctx.scroll_long_fired = true;
709	    }
710	
711	    if (s_ctx.last & LV_PORT_BTN_CLICK) {
712	        s_ctx.click_long_fired = true;
713	    }
714	
715	    if (s_ctx.last & LV_PORT_BTN_PWR) {
716	        s_ctx.pwr_long_fired = true;
717	    }
718	}
