774	void lv_port_buttons_init(void)
775	{
776	    if (s_ctx.disp != NULL) {
777	        return;
778	    }
779	
780	    s_ctx.fd = open(LV_PORT_BTN_PATH, O_RDONLY | O_NONBLOCK);
781	    if (s_ctx.fd < 0) {
782	        BTN_LOG("open %s failed errno=%d", LV_PORT_BTN_PATH, errno);
783	        LV_LOG_WARN("btn: open %s failed (%d)", LV_PORT_BTN_PATH, errno);
784	        return;
785	    }
786	
787	    s_ctx.disp = lv_display_get_default();
