789	        close(s_ctx.fd);
790	        s_ctx.fd = -1;
791	        return;
792	    }
793	
794	    s_ctx.last = lv_port_btn_read();
795	    /* 开机时用户可能还按着 PWR，不能把这次当单击或 2s 关机。 */
796	    s_ctx.pwr_long_fired = (s_ctx.last & LV_PORT_BTN_PWR) != 0;
797	    s_ctx.pwr_press_tick = lv_tick_get();
