805	    lv_timer_create(lv_port_btn_timer, LV_PORT_POLL_MS, NULL);
806	
807	    BTN_LOG("ready fd=%d KEY1=PA30 KEY2=PA33 PWR=PA34 last=0x%02x",
808	            s_ctx.fd, (unsigned)s_ctx.last);
809	    LV_LOG_USER("btn: KEY1=PA30 KEY2=PA33 PWR=PA34 (click=bl, long 2s=off)");
