111	             sizeof(struct companion_notif_item) * COMPANION_NOTIF_INBOX_MAX);
112	    }
113	
114	  if (g_bridge.pending != NULL)
115	    {
116	      memset(g_bridge.pending, 0,
117	             sizeof(struct companion_notif_item) * COMPANION_NOTIF_QUEUE_MAX);
118	    }
