142	/**
143	 * @brief 若未过期则拷贝最近一次手机 GNSS。
144	 */
145	bool companion_bridge_gnss_get(struct companion_gnss_fix *out)
146	{
147	  bool ok = false;
148	  uint32_t now;
149	
150	  if (out == NULL)
151	    {
152	      return false;
153	    }
154	
155	  now = bridge_now_ms();
156	  bridge_init();
157	  pthread_mutex_lock(&g_bridge.lock);
158	  if (g_bridge.gnss_fresh &&
159	      g_bridge.gnss_ms != 0 &&
160	      myvendor_mono_elapsed_ms(now, g_bridge.gnss_ms) < GNSS_STALE_MS)
161	    {
162	      *out = g_bridge.gnss;
163	      ok = true;
164	    }
165	
166	  pthread_mutex_unlock(&g_bridge.lock);
167	  return ok;
168	}
