170	/**
171	 * @brief 最近一次手机 GNSS 的接收时刻（CLOCK_MONOTONIC 毫秒）；0 表示无。
172	 *
173	 * @details
174	 * 手机 GNSS 与板载一样要能算年龄：消费方把它填进
175	 * myvendor_sys_gnss_t::stamp_ms，就不用为"这份数据是刚到的还是旧的"另开
176	 * 一套判断。本函数只读时间戳，不改 companion_bridge_gnss_get 的过期语义。
177	 */
178	uint32_t companion_bridge_gnss_stamp_ms(void)
179	{
180	  uint32_t ms;
181	
182	  bridge_init();
183	  pthread_mutex_lock(&g_bridge.lock);
184	  ms = g_bridge.gnss_fresh ? g_bridge.gnss_ms : 0u;
185	  pthread_mutex_unlock(&g_bridge.lock);
186	  return ms;
187	}
