237	/**
238	 * @brief 快照传感器遥测；超过 8 s 的字段无效。
239	 */
240	void companion_bridge_sensor_get(struct companion_sensor_telem *out)
241	{
242	  uint32_t now;
243	
244	  if (out == NULL)
245	    {
246	      return;
247	    }
248	
249	  memset(out, 0, sizeof(*out));
250	  now = bridge_now_ms();
251	  bridge_init();
252	
253	  pthread_mutex_lock(&g_bridge.lock);
254	  if (g_bridge.hr_ms != 0 &&
255	      myvendor_mono_elapsed_ms(now, g_bridge.hr_ms) < SENSOR_STALE_MS)
256	    {
257	      out->hr_valid = true;
258	      out->hr_bpm   = g_bridge.hr_bpm;
259	    }
260	
261	  if (g_bridge.cad_ms != 0 &&
262	      myvendor_mono_elapsed_ms(now, g_bridge.cad_ms) < SENSOR_STALE_MS)
263	    {
264	      out->cadence_valid = true;
265	      out->cadence_rpm   = g_bridge.cadence_rpm;
266	    }
267	
268	  if (g_bridge.pwr_ms != 0 &&
269	      myvendor_mono_elapsed_ms(now, g_bridge.pwr_ms) < SENSOR_STALE_MS)
270	    {
271	      out->power_valid = true;
272	      out->power_w     = g_bridge.power_w;
273	    }
274	
275	  pthread_mutex_unlock(&g_bridge.lock);
276	}
