278	/**
279	 * @brief 保存手机导航折线（0xFF19）。
280	 */
281	void companion_bridge_nav_store(const int32_t *lat_e7, const int32_t *lon_e7,
282	                                uint8_t count)
283	{
284	  if (lat_e7 == NULL || lon_e7 == NULL || count == 0)
285	    {
286	      return;
287	    }
288	
289	  if (count > COMPANION_NAV_MAX_PTS)
290	    {
291	      count = COMPANION_NAV_MAX_PTS;
292	    }
293	
294	  bridge_init();
295	  pthread_mutex_lock(&g_bridge.lock);
296	  memcpy(g_bridge.nav_lat, lat_e7, count * sizeof(int32_t));
297	  memcpy(g_bridge.nav_lon, lon_e7, count * sizeof(int32_t));
298	  g_bridge.nav_count   = count;
299	  g_bridge.nav_pending = true;
300	  pthread_mutex_unlock(&g_bridge.lock);
301	}
