303	/**
304	 * @brief 取出挂起的导航折线（一次性）。
305	 */
306	bool companion_bridge_nav_take(int32_t *lat_e7, int32_t *lon_e7,
307	                               uint8_t *count)
308	{
309	  bool ok = false;
310	
311	  if (lat_e7 == NULL || lon_e7 == NULL || count == NULL)
312	    {
313	      return false;
314	    }
315	
316	  bridge_init();
317	  pthread_mutex_lock(&g_bridge.lock);
318	  if (g_bridge.nav_pending && g_bridge.nav_count > 0)
319	    {
320	      memcpy(lat_e7, g_bridge.nav_lat, g_bridge.nav_count * sizeof(int32_t));
321	      memcpy(lon_e7, g_bridge.nav_lon, g_bridge.nav_count * sizeof(int32_t));
322	      *count = g_bridge.nav_count;
323	      g_bridge.nav_pending = false;
324	      ok = true;
325	    }
326	
327	  pthread_mutex_unlock(&g_bridge.lock);
328	  return ok;
329	}
