546	/**
547	 * @brief 投递一条传感器命令（ctl 产品路径；DUMP 不改 sensor_mode）。
548	 */
549	void companion_bridge_sensor_cmd_post(uint8_t cmd)
550	{
551	  bridge_init();
552	  pthread_mutex_lock(&g_bridge.lock);
553	  /* 单槽命令：SCAN_STOP 盖掉 CONNECT 后只会停扫描、永远不建链。 */
554	  if (g_bridge.sensor_cmd_pend &&
555	      cmd == COMPANION_TEST_SENSOR_SCAN_STOP &&
556	      (g_bridge.sensor_cmd == COMPANION_TEST_SENSOR_CONNECT ||
557	       g_bridge.sensor_cmd == COMPANION_TEST_SENSOR_CONNECT_ADDR))
558	    {
559	      pthread_mutex_unlock(&g_bridge.lock);
560	      return;
561	    }
562	
563	  g_bridge.sensor_cmd      = cmd;
564	  g_bridge.sensor_cmd_pend = true;
565	  if (cmd != COMPANION_TEST_SENSOR_DUMP && cmd != COMPANION_TEST_SENSOR_NONE)
566	    {
567	      g_bridge.sensor_mode = cmd;
568	    }
569	
570	  pthread_mutex_unlock(&g_bridge.lock);
571	}
