981	void companion_bridge_notif_post(const struct companion_notif_item *item)
982	{
983	  uint8_t tail;
984	
985	  if (item == NULL)
986	    {
987	      return;
988	    }
989	
990	  bridge_init();
991	  if (g_bridge.inbox == NULL || g_bridge.pending == NULL)
992	    {
993	      return;
994	    }
995	
996	  pthread_mutex_lock(&g_bridge.lock);
997	
998	  if (g_bridge.inbox_n >= COMPANION_NOTIF_INBOX_MAX)
999	    {
1000	      g_bridge.inbox_n = COMPANION_NOTIF_INBOX_MAX - 1u;
1001	    }
1002	
1003	  if (g_bridge.inbox_n > 0)
1004	    {
1005	      memmove(&g_bridge.inbox[1], &g_bridge.inbox[0],
1006	              g_bridge.inbox_n * sizeof(g_bridge.inbox[0]));
1007	    }
1008	
1009	  notif_copy(&g_bridge.inbox[0], item);
1010	  g_bridge.inbox_n++;
1011	
1012	  if (g_bridge.pend_n >= COMPANION_NOTIF_QUEUE_MAX)
1013	    {
1014	      g_bridge.pend_head = (uint8_t)((g_bridge.pend_head + 1u) %
1015	                                     COMPANION_NOTIF_QUEUE_MAX);
1016	      g_bridge.pend_n = COMPANION_NOTIF_QUEUE_MAX - 1u;
1017	    }
1018	
1019	  tail = (uint8_t)((g_bridge.pend_head + g_bridge.pend_n) %
1020	                   COMPANION_NOTIF_QUEUE_MAX);
1021	  notif_copy(&g_bridge.pending[tail], item);
1022	  g_bridge.pend_n++;
1023	
1024	  pthread_mutex_unlock(&g_bridge.lock);
1025	}
