1027	bool companion_bridge_notif_take(struct companion_notif_item *out)
1028	{
1029	  bool ok = false;
1030	
1031	  if (out == NULL)
1032	    {
1033	      return false;
1034	    }
1035	
1036	  memset(out, 0, sizeof(*out));
1037	  bridge_init();
1038	  if (g_bridge.pending == NULL)
1039	    {
1040	      return false;
1041	    }
1042	
1043	  pthread_mutex_lock(&g_bridge.lock);
1044	  if (g_bridge.pend_n > 0)
1045	    {
1046	      notif_copy(out, &g_bridge.pending[g_bridge.pend_head]);
1047	      g_bridge.pend_head = (uint8_t)((g_bridge.pend_head + 1u) %
1048	                                     COMPANION_NOTIF_QUEUE_MAX);
1049	      g_bridge.pend_n--;
1050	      ok = true;
1051	    }
1052	
1053	  pthread_mutex_unlock(&g_bridge.lock);
1054	  return ok;
1055	}
