1057	void companion_bridge_inbox_get(struct companion_notif_item *out, uint8_t *n,
1058	                                uint8_t maxn)
1059	{
1060	  uint8_t i;
1061	  uint8_t count;
1062	
1063	  bridge_init();
1064	  if (g_bridge.inbox == NULL)
1065	    {
1066	      if (n != NULL)
1067	        {
1068	          *n = 0;
1069	        }
1070	
1071	      return;
1072	    }
1073	
1074	  pthread_mutex_lock(&g_bridge.lock);
1075	  count = g_bridge.inbox_n;
1076	  if (n != NULL)
1077	    {
1078	      *n = count;
1079	    }
1080	
1081	  if (out != NULL && maxn > 0)
1082	    {
1083	      if (count > maxn)
1084	        {
1085	          count = maxn;
1086	        }
1087	
1088	      for (i = 0; i < count; i++)
1089	        {
1090	          notif_copy(&out[i], &g_bridge.inbox[i]);
1091	        }
1092	    }
1093	
1094	  pthread_mutex_unlock(&g_bridge.lock);
1095	}
