55	/****************************************************************************
56	 * Name: orb_advsub_open
57	 *
58	 * Description:
59	 *   Open device node as advertiser / subscriber, regist node and save meta
60	 *   in driver for first user, set buffer number for advertisers.
61	 *
62	 * Input Parameters:
63	 *   meta         The uORB metadata (usually from the ORB_ID() macro)
64	 *   flag         The open flag.
65	 *   instance     Instance number to open.
66	 *   queue_size   Maximum number of buffered elements.
67	 *   wakeup       The wakeup flag.
68	 *
69	 * Returned Value:
70	 *   fd on success, otherwise returns a negated errno value on failure.
71	 ****************************************************************************/
72	
73	static int orb_advsub_open(FAR const struct orb_metadata *meta, int flags,
74	                           int instance, unsigned int queue_size,
75	                           FAR orb_info_t *info, bool wakeup)
76	{
77	  char path[ORB_PATH_MAX];
78	  int fd;
79	  int ret;
80	  int err;
81	
82	  snprintf(path, ORB_PATH_MAX, ORB_SENSOR_PATH"%s%d", meta->o_name,
83	           instance);
84	
85	  /* Check existance before open */
86	
87	  flags |= O_CLOEXEC;
88	  fd = open(path, flags);
89	  if (fd < 0)
90	    {
91	      struct sensor_reginfo_s reginfo;
92	      strlcpy(reginfo.path, path, NAME_MAX);
93	      reginfo.esize   = meta->o_size;
94	      reginfo.nbuffer = queue_size;
95	      reginfo.persist = !!(flags & SENSOR_PERSIST);
96	      if (info != NULL)
97	        {
98	          memcpy(&reginfo.devinfo, info, sizeof(*info));
99	        }
100	      else
101	        {
102	          memset(&reginfo.devinfo, 0, sizeof(*info));
103	        }
104	
105	      fd = open(ORB_USENSOR_PATH, O_WRONLY | O_CLOEXEC);
106	      if (fd < 0)
107	        {
108	          return -errno;
109	        }
110	
111	      /* Register new device node */
112	
113	      ret = ioctl(fd, SNIOC_REGISTER, (unsigned long)(uintptr_t)&reginfo);
114	      err = errno;
115	      close(fd);
116	      if (ret < 0 && err != EEXIST)
117	        {
118	          return -errno;
119	        }
120	
121	      fd = open(path, flags);
122	      if (fd < 0)
123	        {
124	          return -errno;
125	        }
126	
127	      if (err != EEXIST)
128	        {
129	          ioctl(fd, SNIOC_SET_USERPRIV, (unsigned long)(uintptr_t)meta);
130	        }
131	    }
132	
133	  /* Only first advertiser can successfully set buffer number */
134	
135	  if (queue_size)
136	    {
137	      ioctl(fd, SNIOC_SET_BUFFER_NUMBER, (unsigned long)queue_size);
138	    }
139	
140	  if (wakeup)
141	    {
142	      ioctl(fd, SNIOC_SET_WAKEUP, (unsigned long)wakeup);
143	    }
144	
145	  return fd;
146	}
