148	static int
149	orb_advertise_multi_queue_flags(FAR const struct orb_metadata *meta,
150	                                FAR const void *data, FAR int *instance,
151	                                unsigned int queue_size, int flags,
152	                                FAR orb_info_t *info)
153	{
154	  int inst;
155	  int fd;
156	
157	  /* Open the node as an advertiser */
158	
159	  inst = instance ? *instance : orb_group_count(meta);
160	
161	  fd = orb_advsub_open(meta, flags, inst, queue_size, info, false);
162	  if (fd < 0)
163	    {
164	      uorberr("%s advertise failed (%i)", meta->o_name, fd);
165	      return -1;
166	    }
167	
168	  /* The advertiser may perform an initial publish to initialise the object */
169	
170	  if (data != NULL)
171	    {
172	      int ret;
173	
174	      ret = orb_publish_multi(fd, data, meta->o_size);
175	      if (ret != meta->o_size)
176	        {
177	          uorberr("%s publish %d, expect %d",
178	                  meta->o_name, ret, meta->o_size);
179	          close(fd);
180	          return -1;
181	        }
182	    }
183	
184	  return fd;
185	}
