  slot->last_loc      = -1;
  slot->last_bpm      = 0;
  slot->last_csc_rpm  = 0;
  slot->last_cps_w    = 0;
  slot->meas_idle     = false;
  slot->drop_link     = false;
  slot->probe_sent    = false;
  slot->probe_ms      = 0;
  slot->bat_ms        = 0;
  slot->notify_ms     = 0;
  slot->meas_sub_ok   = false;
  slot->sub_fail      = 0;
  slot->hci_gone      = false;
  slot->hci_reason    = 0;
  slot->adv_live      = 0;
  {
