bool ble_sensor_owns_addr(const bt_address_t *addr)
{
  uint8_t i;

  if (addr == NULL)
    {
      return false;
    }

  for (i = 0; i < SENSOR_KIND_COUNT; i++)
    {
      if (!addr_empty(&g_slots[i].addr) && addr_eq(&g_slots[i].addr, addr))
        {
          return true;
        }
    }

  return false;
}

